window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[82]={"id":"082","numero":82,"titre":"Altération aiguë de la vision","objectifs":[{"id":"82-1","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir déterminer si un trouble visuel est mono- ou binoculaire","contenu":"<p>La <strong>première étape</strong> devant tout trouble visuel aigu est de déterminer s'il est <span class=\"kw-def\">mono- ou binoculaire</span>, car cela <strong>oriente immédiatement la localisation anatomique</strong> de la <span class=\"kw-clinique\">lésion</span>.</p>\n\n      <table >\n        <thead>\n          <tr><th>Trouble visuel</th><th>Localisation de l'atteinte</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Monoculaire</strong></td>\n            <td>\n              <ul>\n                <li>Atteinte <span class=\"kw-def\">pré-chiasmatique</span> (globe oculaire ou nerf optique)</li>\n                <li>Possible atteinte de la <span class=\"kw-def\">partie latérale du chiasma</span> où passent <span class=\"kw-clinique\">les</span> fibres de l'hémirétine temporale (rare)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Binoculaire</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-def\">Atteinte cérébrale</span> le plus souvent</li>\n                <li>Atteinte du <span class=\"kw-def\">chiasma</span> ou des <span class=\"kw-def\">voies visuelles rétrochiasmatiques</span></li>\n                <li>Atteinte <span class=\"kw-def\">bilatérale du globe oculaire ou du nerf optique</span> (plus rare)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Astuce pratique.</strong> Demander au patient de <em>boucher alternativement chaque œil</em> : si le trouble persiste à un œil et disparaît à l'autre → monoculaire (atteinte pré-chiasmatique).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 81 — RPM et examens · 100 — <span class=\"kw-clinique\">Céphalées</span> · 340 — <span class=\"kw-def\">AVC</span></em></p>","frequence":0},{"id":"82-2","rang":"A","rubrique":"Définition","titre":"Connaître la définition, la signification, et la démarche étiologique devant une cécité monoculaire transitoire","contenu":"<p>La <strong>cécité monoculaire transitoire (CMT)</strong>, aussi appelée <em>amaurose fugace</em>, est une <span class=\"kw-alerte\">urgence diagnostique</span> 🔥 : c'est l'équivalent rétinien d'un <span class=\"kw-def\">AIT</span> et fait courir le risque d'une OACR constituée ou d'un <span class=\"kw-def\"><span class=\"kw-def\">AVC</span> <span class=\"kw-etio\">ischémique</span></span>.</p>\n\n      <table >\n        <thead>\n          <tr><th></th><th>CMT (amaurose fugace)</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Définition</strong></td>\n            <td>Disparition totale de la vision (ou simple flou visuel, ou amputation du champ de vision), pendant <span class=\"kw-def\">quelques minutes à quelques heures</span>, <span class=\"kw-def\">spontanément résolutive</span> (habituellement &lt;<span class=\"kw-chiffre\"> 10 min</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Mécanisme</strong></td>\n            <td>Il s'agit d'un <span class=\"kw-alerte\">AIT rétinien</span>, généralement <span class=\"kw-def\">embolique</span></td>\n          </tr>\n          <tr>\n            <td><strong>Signes associés</strong></td>\n            <td>Le plus souvent isolée, peut s'associer à des signes neurologiques controlatéraux (syndrome opticopyramidal = CMT du côté de la <span class=\"kw-clinique\">lésion</span> + <span class=\"kw-clinique\">hémiparésie</span> controlatérale)</td>\n          </tr>\n          <tr>\n            <td><strong>Gravité</strong></td>\n            <td><span class=\"kw-alerte\">Urgence diagnostique 🔥</span> — risque d'OACR constituée ou d'<span class=\"kw-def\"><span class=\"kw-def\">AVC</span> <span class=\"kw-etio\">ischémique</span></span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Fond d'œil</span></strong></td>\n            <td>Recherche d'<span class=\"kw-clinique\">emboles de cholestérol</span> au niveau des bifurcations artérielles (rare mais <strong>pathognomonique</strong>)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Démarche étiologique à mener en <span class=\"kw-alerte\">urgence</span></h4>\n      <table >\n        <thead>\n          <tr><th>Étiologie</th><th>Bilan urgent</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Athérome</span> carotidien</strong></td>\n            <td><span class=\"kw-clinique\">Imagerie des vaisseaux du cou en urgence</span> : <span class=\"kw-imagerie\">écho-<span class=\"kw-imagerie\">doppler</span></span>, <span class=\"kw-imagerie\">angio-<span class=\"kw-imagerie\">IRM</span></span> ou <span class=\"kw-imagerie\">angio-<span class=\"kw-imagerie\">TDM</span></span> des TSAO</td>\n          </tr>\n          <tr>\n            <td><strong>Cardiopathie emboligène</strong></td>\n            <td><span class=\"kw-clinique\">ECG</span>, <span class=\"kw-clinique\">échocardiographie</span>, <span class=\"kw-clinique\">holter-ECG</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Maladie de Horton</span></strong> (à évoquer systématiquement après <span class=\"kw-chiffre\">50 ans</span>)</td>\n            <td><span class=\"kw-bio\">VS + CRP</span> en <span class=\"kw-alerte\">urgence</span> (<span class=\"kw-ttt\">corticothérapie</span> sans délai si suspicion)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> Une CMT peut être <em>la première manifestation d'une <span class=\"kw-clinique\">maladie de Horton</span></em> chez le sujet &gt;<span class=\"kw-chiffre\"> 50 ans</span> — toujours doser <span class=\"kw-bio\">VS</span>/<span class=\"kw-bio\">CRP</span> même devant un épisode unique et bref.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 81 — Altération de la fonction visuelle · 195 — Artérite à cellules géantes · 340 — <span class=\"kw-def\"><span class=\"kw-def\">AVC</span> <span class=\"kw-etio\">ischémique</span></span></em></p>","frequence":1},{"id":"82-3","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir interpréter un réflexe photomoteur direct et consensuel (voir item 81)","contenu":"<p>Le <strong>réflexe photomoteur (RPM)</strong> est un examen clé pour distinguer une atteinte du <span class=\"kw-def\">capteur sensoriel</span> (rétine + nerf optique pré-chiasmatique) d'une atteinte centrale.</p>\n\n      <table >\n        <thead>\n          <tr><th>Atteinte</th><th>RPM direct (œil éclairé)</th><th>RPM consensuel (œil controlatéral)</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Œil sain</strong></td>\n            <td>Présent (myosis)</td>\n            <td>Présent (myosis controlatéral)</td>\n          </tr>\n          <tr>\n            <td><strong>OACR / atteinte sévère du nerf optique pré-chiasmatique</strong></td>\n            <td><span class=\"kw-alerte\">Aboli</span> à l'éclairement de l'œil atteint</td>\n            <td><span class=\"kw-clinique\">Conservé</span> à l'éclairement de l'œil controlatéral sain</td>\n          </tr>\n          <tr>\n            <td><strong>NOIA / NORB</strong> — signe de Marcus Gunn (déficit pupillaire afférent relatif)</td>\n            <td><span class=\"kw-clinique\">Diminué</span> à l'éclairement de l'œil atteint</td>\n            <td><span class=\"kw-clinique\">Conservé</span> à l'éclairement de l'œil sain</td>\n          </tr>\n          <tr>\n            <td><strong>Cécité corticale</strong> (atteinte des <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>2</span> l</span>obes occipitaux)</td>\n            <td><span class=\"kw-clinique\">Conservé</span> (+++)</td>\n            <td><span class=\"kw-clinique\">Conservé</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Règle clé.</strong> Un RPM <em>conservé</em> avec cécité bilatérale brutale + examen ophtalmologique normal oriente vers une <span class=\"kw-alerte\">cécité corticale</span> (<span class=\"kw-def\">AVC</span> vertébrobasilaire).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 81 — Altération de la fonction visuelle · 104 — <span class=\"kw-ttt\">Sclérose</span> en plaques · 340 — <span class=\"kw-def\">AVC</span></em></p>","frequence":0},{"id":"82-4","rang":"A","rubrique":"Contenu multimédia","titre":"Interpréter un réflexe photomoteur direct et consensuel (voir item 81)","contenu":"<p>L'interprétation pratique du RPM repose sur la <strong>comparaison systématique</strong> direct / consensuel en éclairant chaque œil alternativement (<em>swinging flashlight test</em>).</p>\n\n      <table >\n        <thead>\n          <tr><th>Situation clinique</th><th>Réponse pupillaire attendue</th><th>Interprétation</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>OACR aiguë</strong></td>\n            <td><span class=\"kw-clinique\">Mydriase aréflective</span> dès <span class=\"kw-clinique\">les</span> 1ères minutes — RPM direct aboli, consensuel conservé en éclairant l'œil sain</td>\n            <td>Atteinte pré-chiasmatique <strong>sévère</strong> du capteur (toutes <span class=\"kw-clinique\">les</span> fibres ganglionnaires de l'<span class=\"kw-alerte\">ACR</span> détruites)</td>\n          </tr>\n          <tr>\n            <td><strong>NOIA aiguë</strong></td>\n            <td><span class=\"kw-clinique\">Signe de Marcus Gunn</span> : <span class=\"kw-clinique\">asymétrie</span> avec diminution du RPM direct à l'éclairement de l'œil atteint, RPM consensuel conservé</td>\n            <td>Atteinte <strong>partielle</strong> du nerf optique antérieur → déficit pupillaire afférent <em>relatif</em></td>\n          </tr>\n          <tr>\n            <td><strong>Cécité corticale</strong></td>\n            <td>RPM direct et consensuel <span class=\"kw-clinique\">conservés bilatéralement</span></td>\n            <td>Capteur sensoriel intact, mais <strong>absence d'interprétation corticale du signal</strong> → <span class=\"kw-def\">AVC</span> vertébrobasilaire</td>\n          </tr>\n          <tr>\n            <td><strong>Aura migraineuse</strong></td>\n            <td>RPM normaux après la crise</td>\n            <td><span class=\"kw-def\">Critère diagnostique</span> : <strong>examen neurologique et ophtalmologique normaux après la crise</strong></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> Une mydriase aréflective unilatérale dans un contexte de BAV brutale + œil blanc indolore = <span class=\"kw-alerte\">OACR jusqu'à preuve du contraire</span> → <span class=\"kw-imagerie\">fond d'œil</span> en <span class=\"kw-alerte\">urgence</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 81 — RPM · obj-2 de cet item</em></p>","frequence":1},{"id":"82-5","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les principaux examens complémentaires en ophtalmologie et leurs indications","contenu":"<p><span class=\"kw-clinique\">Les</span> examens complémentaires en ophtalmologie sont <strong>guidés par la suspicion clinique</strong> (atteinte oculaire, nerf optique, chiasma, voies rétrochiasmatiques, mécanisme vasculaire/<span class=\"kw-etio\">inflammatoire</span>).</p>\n\n      <table >\n        <thead>\n          <tr><th>Suspicion</th><th>Examens complémentaires orientés</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Atteinte oculaire</strong></td>\n            <td>Selon le contexte : <span class=\"kw-imagerie\">Écho B</span> (si hémorragie du vitré), <span class=\"kw-imagerie\">OCT</span>, <span class=\"kw-imagerie\">angiographie à la fluorescéine</span>…</td>\n          </tr>\n          <tr>\n            <td><strong>Atteinte des nerfs optiques</strong></td>\n            <td><span class=\"kw-imagerie\">IRM des nerfs optiques</span>, <span class=\"kw-imagerie\">PEV</span> (potentiels évoqués visuels)…</td>\n          </tr>\n          <tr>\n            <td><strong>Atteinte chiasmatique ou rétrochiasmatique</strong></td>\n            <td><span class=\"kw-imagerie\">IRM cérébrale</span> (ou <span class=\"kw-imagerie\">TDM</span> à défaut), <span class=\"kw-imagerie\">enregistrement du champ visuel</span></td>\n          </tr>\n          <tr>\n            <td><strong>Mécanisme vasculaire (brutal)</strong></td>\n            <td><span class=\"kw-imagerie\">Échodoppler des TSAO</span>, <span class=\"kw-imagerie\">échocardiographie</span>, <span class=\"kw-imagerie\">holter-ECG</span>, <span class=\"kw-bio\">bilan biologique</span>…</td>\n          </tr>\n          <tr>\n            <td><strong>Mécanisme <span class=\"kw-etio\">inflammatoire</span></strong></td>\n            <td><span class=\"kw-bio\">VS, CRP</span>, <span class=\"kw-bio\">ponction lombaire</span>…</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Examens spécifiques à connaître</h4>\n      <table >\n        <thead>\n          <tr><th>Examen</th><th>Apport / indication</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-imagerie\">OCT</span></strong> (tomographie par cohérence optique)</td><td>mesure de l'épaisseur rétinienne, suit l'<span class=\"kw-clinique\">œdème maculaire</span>, l'<span class=\"kw-clinique\">œdème papillaire</span>, l'<span class=\"kw-clinique\">atrophie</span></td></tr>\n          <tr><td><strong><span class=\"kw-imagerie\">Angiographie</span> à la fluorescéine</strong></td><td>temps bras-rétine, perfusion choroïdienne/rétinienne, territoires non perfusés, <span class=\"kw-imagerie\">diffusion</span> à partir des néovaisseaux</td></tr>\n          <tr><td><strong><span class=\"kw-imagerie\">OCT</span>-<span class=\"kw-imagerie\">angiographie</span> (OCT-A)</strong></td><td>évaluation non invasive de la perfusion capillaire rétinienne</td></tr>\n          <tr><td><strong>Écho B</strong></td><td>essentielle quand la rétine n'est <em>pas visible</em> au <span class=\"kw-imagerie\">FO</span> (hémorragie vitré massive) — <strong>élimine un décollement de rétine sous-jacent</strong> ⚠️</td></tr>\n          <tr><td><strong>Champ visuel</strong> (Goldmann ou automatisé)</td><td>périmétrie cinétique pour NOIA, automatisée pour pathologies chroniques</td></tr>\n          <tr><td><strong>PEV</strong></td><td>confirmation d'une atteinte des voies visuelles au-delà de la rétine</td></tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 81 — Bilan ophtalmo standard · 100 — <span class=\"kw-imagerie\">IRM</span> dans <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">céphalées</span></em></p>","frequence":1},{"id":"82-6","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales causes d’atteinte des voies optiques et du nerf optique et identifier les étiologies nécessitant une prise en charge urgente (névrite optique ischémique antérieure aiguë (NOIAA), œdème papillaire)","contenu":"<p><span class=\"kw-clinique\">Les</span> atteintes des voies optiques et du nerf optique se répartissent selon le <span class=\"kw-def\">site anatomique</span> et imposent d'identifier les <span class=\"kw-alerte\">étiologies urgentes</span> 🔥.</p>\n\n      <h4>Étiologies par site anatomique</h4>\n      <table >\n        <thead>\n          <tr><th>Site</th><th>Étiologies principales</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Nerf optique (pré-chiasmatique)</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-alerte\">NOIAA</span> (Horton ++) — <span class=\"kw-alerte\">urgence</span> 🔥</li>\n                <li><span class=\"kw-clinique\">NORB</span> (SEP ++)</li>\n                <li><span class=\"kw-clinique\">Œdème papillaire de stase</span> par <span class=\"kw-alerte\">HTIC</span></li>\n                <li>Neuropathies optiques tumorales (gliome, méningiome de la gaine)</li>\n                <li>Neuropathies optiques toxiques/médicamenteuses : <span class=\"kw-ttt\">antituberculeux (isoniazide, éthambutol)</span>, <span class=\"kw-etio\">alcool</span>-<span class=\"kw-etio\">tabac</span>, plomb</li>\n                <li>Neuropathies optiques métaboliques : <span class=\"kw-def\">diabète</span></li>\n                <li>Traumatismes</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Chiasma</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Adénome hypophysaire</span> (étiologie principale) → hémianopsie bitemporale</li>\n                <li>Adulte : méningiome du tubercule de la selle, anévrisme carotide interne, craniopharyngiome</li>\n                <li>Enfant : gliome du chiasma (NF1 +++), craniopharyngiome</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Voies rétrochiasmatiques</strong> (bandelettes, radiations, cortex)</td>\n            <td>\n              <ul>\n                <li><span class=\"kw-alerte\">Vasculaire (AVC, hématome compressif)</span> — installation brutale 🔥</li>\n                <li><span class=\"kw-etio\">Tumorale</span> — installation progressive</li>\n                <li>Traumatique — apparition contemporaine du traumatisme</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong>🔥 Étiologies urgentes à identifier impérativement.</strong>\n        <ul>\n          <li><strong>NOIAA artéritique (Horton)</strong> : risque de <span class=\"kw-alerte\">bilatéralisation en quelques jours → cécité bilatérale définitive</span>. <span class=\"kw-ttt\">Corticothérapie</span> générale <strong>immédiate</strong>, <em>avant la <span class=\"kw-bio\">biopsie</span> de l'artère temporale</em>.</li>\n          <li><strong><span class=\"kw-clinique\">Œdème</span> papillaire de stase par <span class=\"kw-alerte\">HTIC</span></strong> : justifie une <span class=\"kw-imagerie\">imagerie cérébrale en urgence</span> à la recherche d'une cause <span class=\"kw-etio\">tumorale</span>, <span class=\"kw-etio\">hémorragique</span> ou <span class=\"kw-etio\">thrombotique</span> veineuse.</li>\n          <li><strong>NORB</strong> chez le sujet jeune : <span class=\"kw-clinique\">poussée</span> de SEP probable → <span class=\"kw-imagerie\">IRM</span> cérébrale + médullaire.</li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège SEP.</strong> Une NORB unilatérale chez le sujet jeune peut être <em>la 1ʳᵉ <span class=\"kw-clinique\">poussée</span> de SEP</em> — toujours rechercher d'autres signes neurologiques associés et indiquer une <span class=\"kw-imagerie\">IRM</span> cérébro-médullaire.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 104 — SEP · 195 — Horton · 100 — <span class=\"kw-alerte\">HTIC</span> · 299 — Tumeurs cérébrales</em></p>","frequence":1},{"id":"82-7","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître la conduite à tenir devant une baisse de vision brutale avec œil blanc et identification des urgences","contenu":"<div class=\"callout callout-danger\">\n        <strong>🔥 OBJECTIF MAJEUR EDN (9⭐) — la BAV brutale avec œil blanc indolore est le <em>scénario sentinelle</em> de l'item 82.</strong> La démarche repose sur 2 critères : (1) <span class=\"kw-def\">FO visible ou non</span> ; (2) si visible, <span class=\"kw-def\">FO normal ou anormal</span>.\n      </div>\n\n      <h4>Arbre décisionnel — BAV brutale unilatérale + œil blanc + indolore</h4>\n      <table >\n        <thead>\n          <tr><th><span class=\"kw-imagerie\">FO</span></th><th>Diagnostics à évoquer</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">FO</span> non visible</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Uvéite intermédiaire</span> (± postérieure)</li>\n                <li><span class=\"kw-alerte\">Hémorragie intravitréenne</span> → écho B en <span class=\"kw-alerte\">urgence</span> pour éliminer un DR sous-jacent</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">FO</span> anormal</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-alerte\">OACR</span> — tache rouge cerise, mydriase aréflective</li>\n                <li><span class=\"kw-alerte\">OVCR</span> — veines tortueuses/dilatées, hémorragies en flammèches/tâches, <span class=\"kw-clinique\">œdème</span> papillaire/maculaire, nodules cotonneux</li>\n                <li><span class=\"kw-alerte\">NOIAA</span> — <span class=\"kw-clinique\">œdème</span> papillaire pâle, hémorragies en flammèches, déficit altitudinal</li>\n                <li><span class=\"kw-clinique\">DMLA exsudative</span> — hémorragies maculaires, exsudats secs, <span class=\"kw-clinique\">œdème</span> ou décollement maculaire</li>\n                <li><span class=\"kw-alerte\">DR rhegmatogène</span> — rétine en relief, mobile, plis, déhiscence</li>\n                <li><span class=\"kw-clinique\">Œdème papillaire</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">FO</span> normal</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">NORB</span> — sujet jeune, douleur à la mobilisation oculaire, scotome central, contexte SEP</li>\n                <li>Atteintes des voies optiques chiasmatiques et rétrochiasmatiques</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>🔥 <span class=\"kw-clinique\">Les</span> 5 urgences à reconnaître immédiatement</h4>\n      <table >\n        <thead>\n          <tr><th><span class=\"kw-alerte\">Urgence</span></th><th>Tableau</th><th>CAT immédiate</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>OACR</strong></td>\n            <td>BAV brutale profonde (perception lumineuse), mydriase aréflective, tache rouge cerise</td>\n            <td><span class=\"kw-alerte\">Hospitalisation en UNV</span>, fenêtre &lt;<span class=\"kw-chiffre\"> 6 h</span>, <span class=\"kw-ttt\">aspirine</span>, vasodilatateurs IV, Diamox® ± <span class=\"kw-ttt\">fibrinolyse</span></td>\n          </tr>\n          <tr>\n            <td><strong>NOIAA artéritique (Horton)</strong></td>\n            <td>BAV brutale + signes Horton + <span class=\"kw-bio\">VS</span>/<span class=\"kw-bio\">CRP</span> élevées</td>\n            <td><span class=\"kw-alerte\">Corticothérapie IMMÉDIATE</span> avant <span class=\"kw-bio\">biopsie</span> temporale, prévention de la bilatéralisation</td>\n          </tr>\n          <tr>\n            <td><strong>Décollement de rétine</strong></td>\n            <td>Myodésopsies → phosphènes → amputation <span class=\"kw-bio\">CV</span> périphérique → BAV si macula soulevée</td>\n            <td><span class=\"kw-ttt\">Chirurgie</span> en <span class=\"kw-alerte\">&lt; 1 semaine</span> (encore plus urgent si macula à plat)</td>\n          </tr>\n          <tr>\n            <td><strong>OVCR <span class=\"kw-etio\">ischémique</span></strong></td>\n            <td>BAV brutale effondrée (&lt; 1/10), nombreuses hémorragies + nodules cotonneux</td>\n            <td>PPR d'emblée pour prévenir glaucome néovasculaire, anti-VEGF si OM</td>\n          </tr>\n          <tr>\n            <td><strong>Hémorragie du vitré</strong></td>\n            <td>« Pluie de suie » → BAV brutale, <span class=\"kw-imagerie\">FO</span> non visible</td>\n            <td><span class=\"kw-imagerie\">Écho B</span> systématique pour éliminer un DR sous-jacent</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Œil rouge avec BAV — autres urgences (item 81)</h4>\n      <table >\n        <thead>\n          <tr><th><span class=\"kw-alerte\">Urgence</span></th><th>Signes / particularité</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Kératite</span></td><td>pas de <span class=\"kw-ttt\">corticoïdes</span> locaux sans diagnostic</td></tr>\n          <tr><td><span class=\"kw-clinique\">Uvéite antérieure</span></td><td>synéchies, précipités rétrodescémétiques</td></tr>\n          <tr><td><span class=\"kw-alerte\">Glaucome aigu par fermeture de l'angle (CAFA)</span></td><td>cécité unilatérale, douleur, syndrome digestif, mydriase, HTO majeure</td></tr>\n          <tr><td><span class=\"kw-alerte\">Endophtalmie</span> (suspicion postopératoire +++)</td><td><span class=\"kw-alerte\">urgence</span> absolue</td></tr>\n          <tr><td><span class=\"kw-clinique\">Glaucome néovasculaire</span></td><td>—</td></tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 81 — Œil rouge · 195 — Horton · 104 — SEP · obj-7 imagerie · obj-14 DR</em></p>","frequence":9},{"id":"82-8","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications de l’imagerie devant un trouble visuel récent","contenu":"<p>L'imagerie devant un trouble visuel récent vise à <strong>identifier une cause centrale</strong> (chiasma, voies rétrochiasmatiques, cortex visuel) ou une <strong>complication intracrânienne</strong> (<span class=\"kw-alerte\">HTIC</span>, <span class=\"kw-def\">AVC</span>).</p>\n\n      <div class=\"callout callout-info\">\n        <strong>🧠 5 situations imposant une imagerie cérébrale en <span class=\"kw-alerte\">urgence</span>.</strong>\n        <ul>\n          <li>Cécité monoculaire transitoire (<strong>CMT</strong>)</li>\n          <li>Névrite optique rétrobulbaire (<strong>NORB</strong>)</li>\n          <li><strong>OACR</strong> (équivalent rétinien d'un <span class=\"kw-def\"><span class=\"kw-def\">AVC</span> <span class=\"kw-etio\">ischémique</span></span>)</li>\n          <li>Atteinte du champ visuel de type <strong>HLH ou hémianopsie bitemporale</strong></li>\n          <li><strong><span class=\"kw-clinique\">Œdème</span> papillaire bilatéral</strong> (<span class=\"kw-alerte\">HTIC</span> à évoquer)</li>\n        </ul>\n      </div>\n\n      <h4>Indications selon le contexte clinique</h4>\n      <table >\n        <thead>\n          <tr><th>Tableau</th><th>Imagerie de <span class=\"kw-chiffre\">1ère intention</span></th><th>Justification</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>BAV binoculaire + déficit campimétrique</td>\n            <td><span class=\"kw-imagerie\">IRM cérébrale</span> (<span class=\"kw-imagerie\">TDM</span> à défaut)</td>\n            <td>Recherche d'une atteinte chiasmatique (adénome hypophysaire) ou rétrochiasmatique</td>\n          </tr>\n          <tr>\n            <td>NORB du sujet jeune</td>\n            <td><span class=\"kw-imagerie\">IRM cérébrale + médullaire</span> avec injection</td>\n            <td>Recherche d'une SEP (plaques de démyélinisation)</td>\n          </tr>\n          <tr>\n            <td>OACR</td>\n            <td><span class=\"kw-imagerie\">IRM cérébrale + angio-IRM TSAO</span></td>\n            <td>OACR = <span class=\"kw-def\">AVC</span> rétinien — <span class=\"kw-alerte\">hospitalisation</span> en UNV</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Œdème</span> papillaire bilatéral</td>\n            <td><span class=\"kw-imagerie\">IRM cérébrale + ARM veineuse</span></td>\n            <td><span class=\"kw-alerte\">HTIC</span> : éliminer une cause <span class=\"kw-etio\">tumorale</span>, <span class=\"kw-etio\">hémorragique</span> ou une thrombose veineuse cérébrale</td>\n          </tr>\n          <tr>\n            <td>Aura migraineuse <strong>atypique</strong> (âge tardif, durée, fréquence ou chronologie inhabituelles)</td>\n            <td><span class=\"kw-imagerie\">IRM cérébrale</span></td>\n            <td>Éliminer une cause secondaire (<span class=\"kw-clinique\">lésion</span> occipitale, MAV, tumeur)</td>\n          </tr>\n          <tr>\n            <td>Cécité corticale</td>\n            <td><span class=\"kw-imagerie\">IRM cérébrale</span></td>\n            <td><span class=\"kw-def\">AVC</span> dans le territoire vertébrobasilaire (lobes occipitaux bilatéraux)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 100 — <span class=\"kw-clinique\">Céphalées</span> · 340 — <span class=\"kw-def\">AVC</span> · 104 — SEP</em></p>","frequence":0},{"id":"82-9","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques des affections vasculaires de la rétine (occlusion de l’artère centrale de la rétine (OACR), occlusion de la veine centrale de la rétine (OVCR)), leurs complications (néovascularisation , glaucome néovasculaire, œdème maculaire) et les principes de traitement","contenu":"<p><span class=\"kw-clinique\">Les</span> <strong>occlusions artérielles et veineuses rétiniennes</strong> partagent le tableau « <em>œil blanc indolore + BAV brutale</em> » mais s'opposent par leur tableau au <span class=\"kw-imagerie\">fond d'œil</span>, leur <span class=\"kw-clinique\">évolution</span> et leur traitement.</p>\n\n      <h4>Tableau comparatif OACR <span class=\"kw-bio\">vs</span> OVCR</h4>\n      <table >\n        <thead>\n          <tr><th></th><th>OACR</th><th>OVCR</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Fréquence</strong></td>\n            <td>Rare (1/10 000)</td>\n            <td>Plus fréquente (<span class=\"kw-chiffre\">0,1–0,14%</span> OVCR ·<span class=\"kw-chiffre\"> 0,6–1,2%</span> OBVR)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Terrain</span></strong></td>\n            <td>~<span class=\"kw-chiffre\">60 ans</span>, sujet souvent vasculaire</td>\n            <td>&gt;<span class=\"kw-chiffre\"> 50 ans</span> (<span class=\"kw-chiffre\">75%</span> &gt;<span class=\"kw-chiffre\"> 60 ans</span>), <span class=\"kw-etio\">FRCV</span>, GPAO ⭐</td>\n          </tr>\n          <tr>\n            <td><strong>BAV</strong></td>\n            <td><span class=\"kw-alerte\">Brutale, profonde, effondrée (perception lumineuse)</span></td>\n            <td>Brutale, intensité <em>variable</em> selon perfusion capillaire</td>\n          </tr>\n          <tr>\n            <td><strong>RPM</strong></td>\n            <td>Mydriase aréflective dès <span class=\"kw-clinique\">les</span> 1ères minutes ; RPM direct <span class=\"kw-alerte\">aboli</span></td>\n            <td>RPM direct diminué dans <span class=\"kw-clinique\">les</span> formes ischémiques (déficit pupillaire afférent)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">FO</span></strong></td>\n            <td>\n              <ul>\n                <li>Rétrécissement diffus du calibre artériel</li>\n                <li><span class=\"kw-clinique\">Œdème</span> <span class=\"kw-etio\">ischémique</span> rétinien blanchâtre au pôle postérieur</li>\n                <li><span class=\"kw-clinique\">Tache rouge cerise de la macula</span> (fovéola avasculaire intacte)</li>\n                <li>Emboles parfois visibles</li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li>Veines <strong>tortueuses et dilatées</strong></li>\n                <li>Hémorragies disséminées <strong>dans <span class=\"kw-clinique\">les</span> 4 cadrans</strong> : en flammèches (superficielles) et/ou en tâches (profondes)</li>\n                <li><span class=\"kw-clinique\">Œdème</span> papillaire + <span class=\"kw-clinique\">œdème maculaire ⭐</span></li>\n                <li><span class=\"kw-clinique\">Nodules cotonneux ⭐</span> (surtout formes ischémiques)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Angiographie</span></strong></td>\n            <td>Allongement majeur du temps bras-rétine (&gt; plusieurs min <span class=\"kw-bio\">vs</span> &lt; 15 s)</td>\n            <td>Recherche de territoires <strong>non perfusés</strong> &gt; 10 diamètres papillaires (forme <span class=\"kw-etio\">ischémique</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Complications</strong></td>\n            <td>Atrophie optique, papille pâle, artères filiformes, glaucome néovasculaire si pas de <span class=\"kw-ttt\">reperfusion</span></td>\n            <td><span class=\"kw-alerte\">Rubéose irienne</span> → <span class=\"kw-alerte\">glaucome néovasculaire</span> (dès <span class=\"kw-chiffre\">3 mois</span>) · <span class=\"kw-clinique\">œdème maculaire</span> chronique · hémorragie du vitré</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Pronostic</span></strong></td>\n            <td>Très péjoratif (lésions définitives en <span class=\"kw-chiffre\">90 min</span> ·<span class=\"kw-chiffre\"> 6 h</span> max pour <span class=\"kw-ttt\">reperfusion</span>)</td>\n            <td>Forme non-<span class=\"kw-etio\">ischémique</span> 3/4 (<span class=\"kw-chiffre\">50%</span> évoluent favorablement) · forme <span class=\"kw-etio\">ischémique</span> 1/4 (AV &lt; 1/10 sans récupération)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Étiologies — à connaître pour le bilan</h4>\n      <table >\n        <thead>\n          <tr><th></th><th>OACR (= <span class=\"kw-def\">AVC</span> rétinien)</th><th>OVCR</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Embolies</strong></td>\n            <td><span class=\"kw-etio\">Athérome</span> carotidien ++, cardiopathies emboligènes, <span class=\"kw-alerte\">dissection aortique</span> (jeune ++), embolies graisseuses, emboles tumoraux (myxome)</td>\n            <td>—</td>\n          </tr>\n          <tr>\n            <td><strong>Thromboses / mécanismes locaux</strong></td>\n            <td>Maladie de <strong>Horton</strong> (<span class=\"kw-chiffre\">2%</span> des OACR), maladies de système (<span class=\"kw-def\">lupus</span>, <span class=\"kw-clinique\">Wegener</span>, Takayasu, Kawasaki, Churg-Strauss)</td>\n            <td><span class=\"kw-etio\">Athérosclérose</span>, hypertonie oculaire/GPAO, ↗ VEGF intraoculaire</td>\n          </tr>\n          <tr>\n            <td><strong>Coagulopathies</strong></td>\n            <td>SAPL, déficits protéine C/S/antithrombine, hyperhomocystéinémie</td>\n            <td>Anomalie primitive de coagulation, SAPL, hyperhomocystéinémie, hyperviscosité (Waldenström, leucémies, myélome), CO chez la femme</td>\n          </tr>\n          <tr>\n            <td><strong>Bilan systématique</strong></td>\n            <td>UNV, <span class=\"kw-imagerie\">écho-<span class=\"kw-imagerie\">doppler</span></span> TSAO, <span class=\"kw-bio\">ECG</span>/écho/<span class=\"kw-imagerie\">holter</span>, <span class=\"kw-bio\">NFS</span>/<span class=\"kw-bio\">VS</span>/<span class=\"kw-bio\">CRP</span> (Horton ++)</td>\n            <td>&gt;<span class=\"kw-chiffre\"> 50 ans</span> : <span class=\"kw-etio\">FRCV</span> + PIO + <span class=\"kw-bio\">NFS</span>/<span class=\"kw-bio\">VS</span>/<span class=\"kw-bio\">CRP</span> · &lt;<span class=\"kw-chiffre\"> 50 ans</span> ou bilatéral : bilan thrombophilie + hyperviscosité</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Principes de traitement</h4>\n      <table >\n        <thead>\n          <tr><th>Pathologie</th><th>Traitement</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>OACR</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-alerte\">Hospitalisation UNV — traitement analogue à un AVC</span></li>\n                <li><span class=\"kw-ttt\">Aspirine</span> per os ou IV systématique</li>\n                <li>Traitement maximal si <strong>sujet jeune + bon état général + &lt;<span class=\"kw-chiffre\"> 6 h</span></strong> : Diamox®, vasodilatateurs IV, fibrinolytiques (IV ou intra-artériel cathétérisme art. ophtalmique)</li>\n                <li>Au long cours : AAP si <span class=\"kw-etio\">athérome</span>, <span class=\"kw-ttt\">AVK</span> si FA, endartériectomie si sténose carotidienne significative</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>OVCR — forme non-<span class=\"kw-etio\">ischémique</span></strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-ttt\">Anti-VEGF</span> (ranibizumab, aflibercept) ou <span class=\"kw-ttt\">implant DXM</span> intravitréens si <strong><span class=\"kw-clinique\">œdème</span> maculaire + BAV</strong> ⚠️</li>\n                <li><span class=\"kw-def\">Surveillance</span> clinique + angiographique mensuelle (dépister conversion <span class=\"kw-etio\">ischémique</span> :<span class=\"kw-chiffre\"> 25%</span>)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>OVCR — forme <span class=\"kw-etio\">ischémique</span></strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-ttt\">PPR (photocoagulation panrétinienne au laser argon) d'emblée</span> si ischémie étendue (objectif = éviter le glaucome néovasculaire, pas restaurer la vision)</li>\n                <li>Anti-VEGF / implant DXM si <span class=\"kw-clinique\">œdème</span> maculaire associé</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Glaucome néovasculaire installé</strong></td>\n            <td>\n              <ol>\n                <li>Baisser PIO : hypotonisant local + <span class=\"kw-ttt\">acétazolamide (Diamox®)</span> per os ou IV</li>\n                <li><span class=\"kw-ttt\">PPR en urgence</span> après baisse de la PIO</li>\n                <li>Anti-VEGF en adjuvant (régression partielle de la rubéose en attendant le <span class=\"kw-ttt\">laser</span>)</li>\n                <li><span class=\"kw-ttt\">Chirurgie</span> hypotonisante dans <span class=\"kw-clinique\">les</span> cas les plus graves</li>\n              </ol>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>⚠️ Piège des anti-VEGF.</strong> Ils ne sont <em>pas indiqués</em> pour traiter l'ischémie rétinienne (durée d'action trop courte → simple régression transitoire). Et ils sont <strong><span class=\"kw-ci\">contre-indiqués</span></strong> chez <span class=\"kw-clinique\">les</span> patients ayant eu un événement cardio-vasculaire récent.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 224 — <span class=\"kw-etio\">Athérome</span> · 195 — Horton · obj-6 BAV brutale · obj-16 hémorragie vitré</em></p>","frequence":2},{"id":"82-10","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques d’une neuropathie optique (neuropathie optique ischémique antérieure (NOIA), (neuropathie optique rétrobulbaire (NORB), œdème papillaire)","contenu":"<p><span class=\"kw-clinique\">Les</span> <strong>3 neuropathies optiques sentinelles</strong> partagent un tableau de BAV unilatérale brutale ou subaiguë, mais leur étiologie et leur prise en charge divergent radicalement.</p>\n\n      <h4>Tableau comparatif NOIA · NORB · <span class=\"kw-clinique\">œdème</span> papillaire de stase</h4>\n      <table >\n        <thead>\n          <tr><th></th><th>NOIA</th><th>NORB</th><th><span class=\"kw-clinique\">Œdème</span> papillaire de stase</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Mécanisme</strong></td>\n            <td>Ischémie aiguë de la tête du nerf optique par occlusion des artères ciliaires postérieures (ACP)</td>\n            <td>Inflammation/démyélinisation du nerf optique en arrière de la papille</td>\n            <td><span class=\"kw-alerte\">HTIC</span> ou <span class=\"kw-def\">HTA</span> maligne ; refoulement des fibres optiques par stase axonale</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Terrain</span></strong></td>\n            <td>\n              <ul>\n                <li><strong>NOIAA</strong> : Horton +++ (<span class=\"kw-chiffre\">10%</span> des NOIA) ⚠️</li>\n                <li><strong>NOIA non artéritique</strong> (la plus fréquente) : <span class=\"kw-def\">terrain</span> <span class=\"kw-bio\">CV</span> (<span class=\"kw-def\">HTA</span>, <span class=\"kw-def\">diabète</span>, <span class=\"kw-etio\">tabac</span>, <span class=\"kw-bio\">cholestérol</span>, <span class=\"kw-def\">SAOS</span>, <span class=\"kw-def\">migraine</span>)</li>\n              </ul>\n            </td>\n            <td>Sujet jeune (<strong>SEP</strong> +++ dans <span class=\"kw-chiffre\">10–30%</span>)</td>\n            <td>Variable selon cause</td>\n          </tr>\n          <tr>\n            <td><strong>BAV</strong></td>\n            <td><span class=\"kw-alerte\">Brutale</span>, complète d'emblée ou avec atteinte <span class=\"kw-bio\">CV</span> périphérique ; AV de PL à 10/10 (AV normale n'élimine PAS le diagnostic ❌)</td>\n            <td>Rapide, progressive en quelques jours, <span class=\"kw-clinique\">douleur à la mobilisation oculaire</span></td>\n            <td><strong>Bilatéral, sans BAV au début</strong></td>\n          </tr>\n          <tr>\n            <td><strong>RPM</strong></td>\n            <td><span class=\"kw-clinique\">Signe de Marcus Gunn</span> (déficit pupillaire afférent relatif)</td>\n            <td>Signe de Marcus Gunn également</td>\n            <td>Normal</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">FO</span></strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Œdème</span> papillaire <strong>en secteur ou total</strong></li>\n                <li>Papille <strong>pâle</strong>, à bords flous</li>\n                <li>Hémorragies en flammèches au bord papillaire</li>\n              </ul>\n            </td>\n            <td><strong>Normal +++</strong> (« le patient ne voit rien, le médecin ne voit rien »)</td>\n            <td>\n              <ul>\n                <li>Papille <strong>bien colorée</strong>, hyperhémiée, bords flous</li>\n                <li>Sans hémorragies en flammèches</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Champ visuel</strong></td>\n            <td><span class=\"kw-clinique\">Déficit altitudinal</span> à limite horizontale inférieure (spécifique +++), rattaché à la tache aveugle</td>\n            <td>Scotome central ou cæcocentral</td>\n            <td>Simple <strong>élargissement de la tache aveugle</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Bilan en <span class=\"kw-alerte\">urgence</span></strong></td>\n            <td><span class=\"kw-bio\">NFS / VS / CRP ⭐</span> (Horton ?) — <span class=\"kw-imagerie\">OCT</span>, <span class=\"kw-imagerie\">angiographie</span> fluo (signe d'ischémie choroïdienne en faveur de NOIAA)</td>\n            <td><span class=\"kw-imagerie\">IRM cérébrale + médullaire</span></td>\n            <td><span class=\"kw-imagerie\">Imagerie cérébrale en urgence</span> (<span class=\"kw-alerte\">HTIC</span> ?)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong>🔥 NOIAA artéritique (Horton).</strong> Représente <span class=\"kw-chiffre\">10%</span> des NOIA mais <span class=\"kw-alerte\">tout retard diagnostique expose à une bilatéralisation et une cécité bilatérale définitive</span>.\n        <ul>\n          <li>Arguments : signes Horton, <span class=\"kw-def\">syndrome inflammatoire</span>, épisodes d'amaurose fugace précédant la NOIA, défaut de remplissage choroïdien à l'angio.</li>\n          <li>Traitement : <span class=\"kw-ttt\">corticothérapie générale IMMÉDIATE</span> (bolus <span class=\"kw-ttt\">méthylprednisolone</span> ou <span class=\"kw-ttt\">prednisone</span> <span class=\"kw-chiffre\">1 mg/kg/j</span>), avant même la <span class=\"kw-bio\">biopsie</span> temporale.</li>\n          <li>Au long cours : décroissance lente sur <strong><span class=\"kw-chiffre\">18–24 mois</span></strong>, <span class=\"kw-ttt\">aspirine</span> antiagrégante, <span class=\"kw-ttt\">immunosuppresseurs</span> (<span class=\"kw-ttt\">tocilizumab</span>) si corticodépendance.</li>\n        </ul>\n      </div>\n\n      <h4><span class=\"kw-clinique\">Œdème</span> papillaire — orientation selon la latéralité</h4>\n      <table >\n        <thead>\n          <tr><th>Latéralité</th><th>Étiologies</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Bilatéral</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-alerte\">HTIC</span> : <span class=\"kw-clinique\">céphalées</span>, <span class=\"kw-clinique\">nausées</span>/<span class=\"kw-clinique\">vomissements</span>, éclipses visuelles, paralysie du VI</li>\n                <li><span class=\"kw-alerte\">HTA maligne (stade 3)</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Unilatéral</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">NOIA</span> : papille pâle, hémorragies en flammèches, déficit altitudinal</li>\n                <li>OVCR</li>\n                <li>NORB (dans <span class=\"kw-chiffre\">10–30%</span> des cas)</li>\n                <li>Uvéite postérieure</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong><span class=\"kw-clinique\">Évolution</span> NOIA.</strong> <span class=\"kw-clinique\">Œdème</span> papillaire résorption en <span class=\"kw-chiffre\">6–8 semaines</span> → <span class=\"kw-alerte\">atrophie optique séquellaire, pas de récupération visuelle attendre</span> ⚠️. Risque de bilatéralisation sur l'autre œil (surtout Horton).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 104 — SEP · 195 — Horton · 100 — <span class=\"kw-alerte\">HTIC</span> · 224 — <span class=\"kw-etio\">FRCV</span></em></p>","frequence":1},{"id":"82-11","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir évoquer le diagnostic d’aura migraineuse","contenu":"<p>L'<strong>aura migraineuse visuelle</strong> est une cause fréquente de trouble visuel <span class=\"kw-def\">binoculaire transitoire</span> chez l'adulte jeune. Le diagnostic repose sur des éléments cliniques caractéristiques.</p>\n\n      <table >\n        <thead>\n          <tr><th></th><th>Scotome scintillant (aura migraineuse visuelle)</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Manifestations</strong></td>\n            <td>Flou visuel <span class=\"kw-def\">bilatéral</span> avec <span class=\"kw-clinique\">flashs colorés</span> accompagnés d'un <span class=\"kw-clinique\">scotome scintillant</span> qui s'étend en quelques minutes du centre vers la périphérie (ou inversement), affectant un hémichamp homonyme (<strong>HLH</strong>) ou tout le champ visuel</td>\n          </tr>\n          <tr>\n            <td><strong>Durée</strong></td>\n            <td>Régresse en <span class=\"kw-def\">15–20 min</span></td>\n          </tr>\n          <tr>\n            <td><strong>Suite</strong></td>\n            <td>Laisse place à une <span class=\"kw-clinique\">céphalée pulsatile</span> volontiers <strong>hémicrânienne et controlatérale</strong> (peut manquer en cas d'aura sans <span class=\"kw-clinique\">céphalée</span>)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Critères diagnostiques</span></strong></td>\n            <td>\n              <ul>\n                <li>Caractère <strong>récidivant</strong> depuis l'enfance ou l'adolescence</li>\n                <li><strong>Normalité de l'examen neurologique et ophtalmologique après la crise</strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Paraclinique</strong></td>\n            <td>Aucun examen si tableau typique. <span class=\"kw-imagerie\">IRM cérébrale</span> indiquée en cas d'<strong>atypies</strong> : âge tardif de début, durée inhabituelle, fréquence ou chronologie des crises atypiques</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong><span class=\"kw-def\">Physiopathologie</span> clé.</strong> L'aura migraineuse correspond à une <em><span class=\"kw-def\">dépression</span> corticale envahissante</em> partant du cortex occipital — d'où la <strong>marche progressive</strong> du scotome scintillant et le caractère <strong>bilatéral homonyme</strong> (<span class=\"kw-clinique\">les</span> deux hémichamps controlatéraux à l'hémisphère atteint).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 100 — <span class=\"kw-clinique\">Céphalées</span> · 104 — SEP · obj-11 DD aura</em></p>","frequence":0},{"id":"82-12","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les diagnostics différentiels de l’aura migraineuse","contenu":"<p><span class=\"kw-clinique\">Les</span> diagnostics différentiels de l'aura migraineuse couvrent toutes les <strong>atteintes visuelles binoculaires transitoires</strong>. Leur identification est essentielle car certaines sont des urgences vitales.</p>\n\n      <table >\n        <thead>\n          <tr><th>Étiologie</th><th>Manifestations</th><th>Caractéristiques distinctives</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-alerte\">Insuffisance vertébrobasilaire / AIT</span></td>\n            <td>Amaurose transitoire bilatérale ; le plus souvent <strong>hémianopsie ou quadranopsie latérale homonyme</strong></td>\n            <td>\n              <ul>\n                <li>Durée <strong>brève</strong> (<span class=\"kw-bio\">vs</span><span class=\"kw-chiffre\"> 15–20 min</span> aura)</li>\n                <li>Pas de <span class=\"kw-clinique\">céphalée</span> pulsatile à la suite</li>\n                <li>Territoire vertébrobasilaire (rarement sylvien superficiel)</li>\n                <li>→ <span class=\"kw-imagerie\">imagerie cérébrale + artères cervicales/intracrâniennes en urgence</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">Crise d'épilepsie focale</span></td>\n            <td>Trouble visuel paroxystique durant <strong>quelques secondes</strong></td>\n            <td>\n              <ul>\n                <li>Altération de conscience souvent associée</li>\n                <li>Autres manifestations cliniques selon généralisation</li>\n                <li>→ <span class=\"kw-imagerie\">EEG + imagerie cérébrale</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">HTIC</span> (éclipses visuelles ou flou persistant)</td>\n            <td>Disparition totale de la vision pendant <strong>quelques secondes</strong>, déclenchée par <span class=\"kw-clinique\">les</span> <strong>mouvements de la tête / efforts</strong></td>\n            <td>\n              <ul>\n                <li>Souvent <strong>bilatérales</strong></li>\n                <li>Autres signes <span class=\"kw-alerte\">HTIC</span> : <span class=\"kw-clinique\">céphalées</span>, V+, diplopie binoculaire (paralysie VI), <span class=\"kw-clinique\">œdème</span> papillaire bilatéral</li>\n                <li>→ <span class=\"kw-imagerie\">imagerie cérébrale en urgence</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td>Phénomène d'<strong>Uhthoff</strong></td>\n            <td>Flou visuel durant <strong>quelques minutes</strong></td>\n            <td>\n              <ul>\n                <li>Survient à l'<strong>effort physique</strong> ou à l'<strong>exposition à la chaleur</strong></li>\n                <li>Traduit une séquelle de neuropathie optique <span class=\"kw-etio\">inflammatoire</span> (<strong>SEP</strong> ++)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Hypoglycémie</strong></td>\n            <td>Flou visuel bilatéral transitoire</td>\n            <td>Contexte (<span class=\"kw-def\">diabète</span>, jeûne) ; cèdent au resucrage</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong><span class=\"kw-alerte\">Drapeau rouge</span>.</strong> Une <em>première aura visuelle</em> chez un sujet &gt;<span class=\"kw-chiffre\"> 40 ans</span>, ou avec déficit neurologique persistant après l'épisode, ou avec sémiologie atypique (durée &gt;<span class=\"kw-chiffre\"> 1 h</span>, scotome non scintillant, hémianopsie isolée sans marche progressive) impose une <strong><span class=\"kw-imagerie\">IRM</span> cérébrale en <span class=\"kw-alerte\">urgence</span></strong>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 100 — <span class=\"kw-clinique\">Céphalées</span> · 340 — <span class=\"kw-def\">AVC</span> · 104 — SEP · obj-10 aura</em></p>","frequence":0},{"id":"82-13","rang":"B","rubrique":"Contenu multimédia","titre":"Photographie d’un œdème papillaire","contenu":"<p>L'<strong><span class=\"kw-clinique\">œdème</span> papillaire</strong> est défini comme le <span class=\"kw-def\">gonflement de la tête du nerf optique</span>. Sa reconnaissance au <span class=\"kw-imagerie\">fond d'œil</span> est un <span class=\"kw-etio\">acquis</span> EDN. La sémiologie diffère selon l'étiologie.</p>\n\n      <h4>Lecture d'une photo d'<span class=\"kw-clinique\">œdème</span> papillaire — sémiologie à reconnaître</h4>\n      <table >\n        <thead>\n          <tr><th>Type</th><th>Aspect au <span class=\"kw-imagerie\">FO</span></th><th>Cause</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Œdème</span> papillaire de stase (<span class=\"kw-alerte\">HTIC</span>)</strong></td>\n            <td>\n              <ul>\n                <li>Papille <strong>bien colorée</strong>, hyperhémiée</li>\n                <li>Bords <strong>flous</strong>, surélevée</li>\n                <li><strong>Bilatéral</strong></li>\n                <li>Pas d'hémorragies en flammèches majeures</li>\n                <li><span class=\"kw-bio\">CV</span> : simple élargissement de la tache aveugle</li>\n              </ul>\n            </td>\n            <td><span class=\"kw-alerte\">HTIC</span> (tumeur, hémorragie, thrombose veineuse cérébrale), <span class=\"kw-def\">HTA</span> maligne <span class=\"kw-def\">stade</span> 3</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Œdème</span> papillaire de NOIA</strong></td>\n            <td>\n              <ul>\n                <li>Topographie : <strong>en secteur ou total</strong> selon territoire ACP occluse</li>\n                <li>Papille <strong>pâle</strong> (décolorée), bords flous</li>\n                <li>Hémorragies en flammèches fréquentes au bord papillaire</li>\n                <li>Unilatéral le plus souvent</li>\n                <li>BAV présente</li>\n              </ul>\n            </td>\n            <td>NOIAA (Horton) ou NOIA non artéritique (<span class=\"kw-def\">terrain</span> <span class=\"kw-bio\">CV</span>)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Œdème</span> papillaire de l'OVCR</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Œdème</span> papillaire <em>associé</em> à des veines tortueuses/dilatées</li>\n                <li>Hémorragies disséminées dans <span class=\"kw-clinique\">les</span> 4 cadrans</li>\n                <li>Nodules cotonneux (forme <span class=\"kw-etio\">ischémique</span>)</li>\n                <li><span class=\"kw-clinique\">Œdème</span> maculaire</li>\n              </ul>\n            </td>\n            <td>OVCR (par stase de <span class=\"kw-ttt\">drainage</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège diagnostique majeur (à savoir +++).</strong> Devant un <span class=\"kw-clinique\">œdème</span> papillaire :\n        <ul>\n          <li><strong>Bilatéral + bien coloré + sans BAV au début</strong> → <span class=\"kw-alerte\">HTIC</span> → imagerie cérébrale urgente</li>\n          <li><strong>Unilatéral + pâle + BAV brutale + hémorragies en flammèches</strong> → NOIA → <span class=\"kw-bio\">VS</span>/<span class=\"kw-bio\">CRP</span> urgentes (Horton ?)</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 100 — <span class=\"kw-alerte\">HTIC</span> · 195 — Horton · obj-9 neuropathies optiques</em></p>","frequence":0},{"id":"82-14","rang":"B","rubrique":"Contenu multimédia","titre":"Photographie d’un champ visuel des 2 yeux avec hémianopsie (quadranopsie) latérale homonyme (ou bitemporale)","contenu":"<p>La lecture d'un <strong>champ visuel des 2 yeux</strong> est un <span class=\"kw-etio\">acquis</span> EDN pour localiser une <span class=\"kw-clinique\">lésion</span> sur <span class=\"kw-clinique\">les</span> voies optiques. Règle clé : <span class=\"kw-def\">distinguer le champ visuel nasal/temporal vs la rétine nasale/temporale (c'est l'inverse)</span>.</p>\n\n      <h4>Sémiologie à reconnaître sur un champ visuel double</h4>\n      <table >\n        <thead>\n          <tr><th>Anomalie <span class=\"kw-bio\">CV</span></th><th>Localisation lésionnelle</th><th>Étiologie typique</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Hémianopsie bitemporale</strong> (déficit des <span class=\"kw-chiffre\">2 h</span>émichamps temporaux)</td>\n            <td><span class=\"kw-clinique\">Lésion chiasmatique</span> (atteinte des fibres nasales qui décussent)</td>\n            <td>Adénome hypophysaire ++, méningiome tubercule selle, anévrisme carotide interne, craniopharyngiome, gliome (enfant + NF1)</td>\n          </tr>\n          <tr>\n            <td><strong>Quadranopsie bitemporale supérieure</strong></td>\n            <td>Atteinte de la <strong>partie antérieure du chiasma</strong> (compression partielle débutante)</td>\n            <td>Adénome hypophysaire débutant +++</td>\n          </tr>\n          <tr>\n            <td><strong>Quadranopsie bitemporale inférieure</strong></td>\n            <td>Atteinte de la <strong>partie postérieure du chiasma</strong></td>\n            <td><span class=\"kw-clinique\">Lésion</span> compressive plus postérieure</td>\n          </tr>\n          <tr>\n            <td><strong>HLH gauche</strong> (déficit de l'hémichamp gauche des 2 yeux)</td>\n            <td>Atteinte de la <strong>bandelette optique droite</strong> (le déficit est controlatéral à la <span class=\"kw-clinique\">lésion</span>)</td>\n            <td><span class=\"kw-def\">AVC</span>, hématome, tumeur, traumatisme</td>\n          </tr>\n          <tr>\n            <td><strong>Quadranopsie LH supérieure</strong></td>\n            <td>Atteinte des <strong>radiations optiques inférieures controlatérales</strong></td>\n            <td><span class=\"kw-def\">AVC</span> sylvien profond temporal, tumeur temporale</td>\n          </tr>\n          <tr>\n            <td><strong>Quadranopsie LH inférieure</strong></td>\n            <td>Atteinte des <strong>radiations optiques supérieures controlatérales</strong></td>\n            <td><span class=\"kw-def\">AVC</span> pariétal, tumeur pariétale</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Règle d'or pour la lecture du <span class=\"kw-bio\">CV</span>.</strong>\n        <ul>\n          <li><strong>Acuité visuelle conservée</strong> en cas d'HLH ou de QLH, et <strong><span class=\"kw-imagerie\">fond d'œil</span> normal</strong> (atteinte rétrochiasmatique).</li>\n          <li>Une HLH <em>controlatérale</em> à une <span class=\"kw-clinique\">lésion</span> cérébrale = atteinte du <strong>côté opposé</strong> à la déficience (ex : HLH droite = lésion hémisphère gauche).</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 299 — Tumeurs cérébrales · 340 — <span class=\"kw-def\">AVC</span> · 244 — Adénomes hypophysaires</em></p>","frequence":0},{"id":"82-15","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir évoquer un décollement de rétine","contenu":"<p>Le <strong>décollement de rétine (DR) rhegmatogène</strong> est une <span class=\"kw-alerte\">urgence ophtalmologique</span> 🔥 : sans traitement, il évolue inexorablement vers la cécité par destruction irréversible des photorécepteurs.</p>\n\n      <h4>Tétrade clinique évocatrice (« le quatuor des 4 phases »)</h4>\n      <table >\n        <thead>\n          <tr><th>Phase</th><th>Signe fonctionnel</th><th>Substrat physiopathologique</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>1</td>\n            <td><strong>Myodésopsies</strong> (« mouches volantes »)</td>\n            <td>Décollement du vitré postérieur (1ère étape)</td>\n          </tr>\n          <tr>\n            <td>2</td>\n            <td><strong>Phosphènes</strong> (éclairs/flashs fixes, continus)</td>\n            <td>Survenue de la <strong>déchirure rétinienne</strong> — stimulation des récepteurs à l'endroit de la traction</td>\n          </tr>\n          <tr>\n            <td>3</td>\n            <td><strong>Amputation du champ visuel périphérique</strong></td>\n            <td>Constitution du DR — l'amputation est <em>opposée</em> au décollement (DR pôle supérieur → amputation <span class=\"kw-bio\">CV</span> inférieure)</td>\n          </tr>\n          <tr>\n            <td>4</td>\n            <td><strong>Baisse de l'acuité visuelle</strong></td>\n            <td>Soulèvement de la macula par le DR — <strong>signe de mauvais <span class=\"kw-def\">pronostic</span></strong></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong>🔥 Quand évoquer un DR (savoir le citer en QCM).</strong>\n        <ul>\n          <li>Apparition récente de <strong>myodésopsies + phosphènes</strong></li>\n          <li><strong>Amputation périphérique du <span class=\"kw-bio\">CV</span></strong> à type de « rideau » progressif</li>\n          <li>BAV brutale en cas d'atteinte maculaire</li>\n          <li><span class=\"kw-def\">Terrain</span> à risque : <span class=\"kw-clinique\">myope fort (&gt; –6 D)</span>, post-<span class=\"kw-ttt\">chirurgie</span> de cataracte, traumatisme, ATCD personnel ou familial de DR</li>\n        </ul>\n      </div>\n\n      <h4>Conduite à tenir en <span class=\"kw-alerte\">urgence</span></h4>\n      <ul>\n        <li><strong><span class=\"kw-imagerie\">Fond d'œil</span> dilaté en <span class=\"kw-alerte\">urgence</span></strong> : rétine en relief, mobile, formant des plis ± déhiscence visible (déchirures multiples fréquentes ⚠️).</li>\n        <li>Si <strong><span class=\"kw-imagerie\">FO</span> non visible</strong> (hémorragie vitré associée) : <span class=\"kw-imagerie\">échographie B</span> systématique pour rechercher le DR sous-jacent.</li>\n        <li><strong>Positionner le regard du patient vers le bas</strong> en attendant la <span class=\"kw-ttt\">chirurgie</span> (limite l'extension du DR).</li>\n        <li>Le traitement est <span class=\"kw-alerte\">uniquement chirurgical</span> (rang C — pas exigible en détail) :\n          <ul>\n            <li>Délai : <strong>&lt;<span class=\"kw-chiffre\"> 1 semaine</span> si macula soulevée</strong>, encore plus urgent si macula à plat</li>\n            <li><span class=\"kw-def\">Pronostic</span> anatomique ~<span class=\"kw-chiffre\">85%</span> de succès si <span class=\"kw-ttt\">chirurgie</span> précoce</li>\n            <li>Techniques : <span class=\"kw-ttt\">cryothérapie</span>-indentation OU vitrectomie-laser-gaz/silicone</li>\n          </ul>\n        </li>\n        <li>Œil controlatéral : examiner systématiquement (lésions prédisposantes → photocoagulation <span class=\"kw-ttt\">laser</span> argon préventive si bilatéralisation à risque &gt;<span class=\"kw-chiffre\"> 10%</span>).</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : obj-15 présentation DR · obj-16 hémorragie vitré · 81 — Œil rouge/blanc</em></p>","frequence":5},{"id":"82-16","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître la présentation clinique, les modes de survenue, les facteurs de risque des décollements de rétine","contenu":"<p>Le <strong>DR rhegmatogène</strong> (du grec <em>rhegma</em> = déchirure) est la forme la plus fréquente. La compréhension de sa <span class=\"kw-def\">physiopathologie</span> permet d'identifier <span class=\"kw-clinique\">les</span> FR et les présentations à risque.</p>\n\n      <h4><span class=\"kw-clinique\">Les</span> 3 types de DR (à distinguer)</h4>\n      <table >\n        <thead>\n          <tr><th>Type</th><th>Mécanisme</th><th>Étiologies typiques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>DR rhegmatogène</strong></td>\n            <td>Secondaire à une <span class=\"kw-clinique\">déhiscence rétinienne</span> de pleine épaisseur → passage de vitré liquéfié dans l'espace sous-rétinien</td>\n            <td>Idiopathique (sujet âgé), myopie forte, post-<span class=\"kw-ttt\">chirurgie</span> cataracte, traumatisme</td>\n          </tr>\n          <tr>\n            <td><strong>DR exsudatif</strong></td>\n            <td>Exsudation rétinienne sans déhiscence</td>\n            <td><span class=\"kw-def\">HTA</span> maligne, toxémie gravidique, DMLA exsudative</td>\n          </tr>\n          <tr>\n            <td><strong>DR tractionnel</strong></td>\n            <td>Traction vitréorétinienne</td>\n            <td>Rétinopathie diabétique proliférante, uvéite postérieure</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span class=\"kw-def\">Physiopathologie</span> du DR rhegmatogène — chronologie</h4>\n      <ol>\n        <li>Survenue d'une <strong>déhiscence</strong> au niveau de la rétine périphérique (défect pleine épaisseur).</li>\n        <li>Passage de <strong>vitré liquéfié</strong> depuis la cavité vitréenne dans l'<strong>espace sous-rétinien</strong> (entre rétine neurosensorielle et épithélium p<span class=\"kw-chiffre\">igm</span>entaire).</li>\n        <li>Le liquide sous-rétinien (LSR) est réabsorbé par l'épithélium p<span class=\"kw-chiffre\">igm</span>entaire mais avec un <strong>débit insuffisant</strong> → accumulation sous la rétine.</li>\n        <li>Soulèvement de la rétine <strong>de proche en proche</strong> = constitution du DR rhegmatogène.</li>\n      </ol>\n\n      <div class=\"callout callout-warn\">\n        <strong>⏱️ <span class=\"kw-clinique\">Évolution</span> spontanée.</strong> Très péjorative : extension inexorable du DR englobant la macula puis toute la rétine. La rétine décollée subit en <strong>quelques semaines</strong> des lésions <em>irréversibles</em> (arrêt des échanges métaboliques épithélium p<span class=\"kw-chiffre\">igm</span>entaire / vaisseaux choroïdiens → cécité par dysfonction des photorécepteurs).\n      </div>\n\n      <h4><span class=\"kw-def\">Facteurs de risque</span> à connaître</h4>\n      <table >\n        <thead>\n          <tr><th>FR</th><th>Mécanisme / Précisions</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Idiopathique (sujet âgé)</strong></td>\n            <td>Le plus souvent — compliquant un décollement postérieur du vitré (DPV) physiologique du sujet âgé</td>\n          </tr>\n          <tr>\n            <td><strong>Myopie ≥ –6 D</strong></td>\n            <td>Risque <strong>croît avec le degré de myopie</strong> (allongement antéro-postérieur → dégénérescence palissadique périphérique)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Chirurgie</span> de la cataracte (DR de l'aphaque/pseudophaque)</strong></td>\n            <td><strong><span class=\"kw-chiffre\">2%</span></strong> des opérés — parfois plusieurs années après la <span class=\"kw-ttt\">chirurgie</span></td>\n          </tr>\n          <tr>\n            <td><strong>Traumatisme</strong></td>\n            <td>Contondant ou perforant — DR contemporain ou retardé</td>\n          </tr>\n          <tr>\n            <td><strong>ATCD personnel ou familial de DR</strong></td>\n            <td>Risque de bilatéralisation <strong>&gt;<span class=\"kw-chiffre\"> 10%</span></strong> → examen systématique de l'œil controlatéral à la recherche de lésions prédisposantes</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Présentation clinique typique</h4>\n      <ul>\n        <li><strong>Œil blanc + indolore</strong> + signes fonctionnels chronologiques (myodésopsies → phosphènes → amputation <span class=\"kw-bio\">CV</span> → BAV)</li>\n        <li><span class=\"kw-clinique\">FO dilaté</span> : rétine en relief, mobile, plis volumineux, déhiscence(s) visible(s) — <strong>rechercher plusieurs déchirures</strong> (déchirures multiples fréquentes, leur méconnaissance expose à un échec chirurgical ⚠️)</li>\n        <li><span class=\"kw-imagerie\">Échographie</span> B en mode B si <span class=\"kw-imagerie\">FO</span> non visible (hémorragie vitré sur déchirure d'un vaisseau rétinien)</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Prévention chez <span class=\"kw-clinique\">les</span> sujets à risque.</strong> Le traitement préventif repose sur la <span class=\"kw-ttt\">photocoagulation au laser argon</span> autour des lésions prédisposantes (trous, déchirures non compliquées, dégénérescence palissadique) — créer une <em>adhérence chorio-rétinienne</em>. Indications : ATCD de DR controlatéral, myopie forte avec lésions palissadiques.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : obj-14 <span class=\"kw-alerte\">urgence</span> DR · obj-16 hémorragie vitré · 247 — <span class=\"kw-def\">Diabète</span> et œil</em></p>","frequence":2},{"id":"82-17","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques d’une hémorragie du vitré et ses principales causes","contenu":"<p>L'<strong>hémorragie intravitréenne</strong> donne un tableau d'<span class=\"kw-def\">œil blanc indolore + BAV variable + FO mal ou non visible</span>. C'est un signe d'alerte qui impose une démarche étiologique systématique car elle peut <strong>masquer un décollement de rétine</strong> sous-jacent ⚠️.</p>\n\n      <h4>Présentation clinique</h4>\n      <table >\n        <thead>\n          <tr><th></th><th>Hémorragie intra-vitréenne</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Tableau</strong></td>\n            <td>OEIL BLANC INDOLORE + BAV VARIABLE + <span class=\"kw-imagerie\">FO</span> mal ou non visible</td>\n          </tr>\n          <tr>\n            <td><strong>Prodromes</strong></td>\n            <td>Impression de <span class=\"kw-clinique\">« pluie de suie »</span> peut précéder la BAV</td>\n          </tr>\n          <tr>\n            <td><strong>Selon la sévérité</strong></td>\n            <td>\n              <ul>\n                <li><strong>Minime</strong> : myodésopsies ± BAV minime</li>\n                <li><strong>Massive</strong> : BAV sévère, au maximum <strong>acuité visuelle réduite à la perception lumineuse</strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Diagnostic étiologique</span></strong></td>\n            <td>\n              <ul>\n                <li>Si <strong>rétine visible au <span class=\"kw-imagerie\">FO</span></strong> → étiologie facile à reconnaître</li>\n                <li>Si <strong><span class=\"kw-alerte\">hémorragie massive</span> rendant la rétine invisible</strong> → <span class=\"kw-imagerie\">échographie B systématique</span> ⚠️ pour : (1) orienter l'étiologie (ex : déchirure rétinienne), (2) <strong>éliminer un DR sous-jacent</strong> (+++)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Principales causes (à connaître)</h4>\n      <table >\n        <thead>\n          <tr><th>Cause</th><th>Mécanisme / Contexte</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Rétinopathie diabétique proliférante</strong></td>\n            <td><span class=\"kw-alerte\">Rupture</span> de néovaisseaux prérétiniens — cause fréquente chez le diabétique évolué</td>\n          </tr>\n          <tr>\n            <td><strong>Forme <span class=\"kw-etio\">ischémique</span> d'OVCR ou d'OBVR</strong></td>\n            <td><span class=\"kw-alerte\">Rupture</span> des néovaisseaux prérétiniens développés sur ischémie rétinienne</td>\n          </tr>\n          <tr>\n            <td><strong>Déchirure rétinienne (± DR)</strong></td>\n            <td><span class=\"kw-alerte\">Rupture</span> d'un vaisseau rétinien au sein de la déchirure — <strong>impose la recherche d'un DR sous-jacent par écho B</strong></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Syndrome de Terson</span></strong></td>\n            <td>Hémorragie intravitréenne uni- ou bilatérale + <span class=\"kw-alerte\">HSA par rupture d'anévrisme</span> ou HSA traumatique — contexte neurologique aigu</td>\n          </tr>\n          <tr>\n            <td><strong>Plaie perforante ou pénétrante</strong></td>\n            <td>Contexte traumatique évident ; rechercher un corps étranger intra-oculaire (<span class=\"kw-imagerie\">TDM</span> au moindre doute)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong>🔥 Règle d'or.</strong> Toute hémorragie du vitré rendant le <span class=\"kw-imagerie\">FO</span> non visible impose une <span class=\"kw-imagerie\">échographie B en urgence</span> pour rechercher un <strong>décollement de rétine sous-jacent</strong> (qui modifie radicalement la prise en charge — <span class=\"kw-ttt\">chirurgie</span> en &lt;<span class=\"kw-chiffre\"> 1 semaine</span>).\n      </div>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège du <span class=\"kw-clinique\">syndrome de Terson</span>.</strong> Une hémorragie du vitré bilatérale chez un patient avec <span class=\"kw-clinique\">céphalée</span> brutale ou <span class=\"kw-def\">syndrome confusionnel</span> doit faire évoquer une <strong>HSA par <span class=\"kw-alerte\">rupture</span> d'anévrisme</strong> → <span class=\"kw-imagerie\">TDM</span> cérébral / <span class=\"kw-imagerie\">angio-<span class=\"kw-imagerie\">TDM</span></span> cérébral en <span class=\"kw-alerte\">urgence</span>.\n      </div>\n\n      <h4><span class=\"kw-def\">Diagnostic différentiel</span> : hémorragie sous-conjonctivale (à savoir distinguer)</h4>\n      <table >\n        <thead>\n          <tr><th></th><th>Hémorragie sous-conjonctivale</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Définition</strong></td>\n            <td>Extravasation de sang dans l'espace sous-conjonctival</td>\n          </tr>\n          <tr>\n            <td><strong>Tableau</strong></td>\n            <td>OEIL ROUGE INDOLORE <strong>SANS BAV</strong> ; nappe hématique, parfois sensation de tension locale (<span class=\"kw-ttt\">anticoagulants</span> ++)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Évolution</span></strong></td>\n            <td>Régresse spontanément en quelques semaines</td>\n          </tr>\n          <tr>\n            <td><strong>Étiologies</strong></td>\n            <td>\n              <ul>\n                <li>Sans traumatisme : <span class=\"kw-def\">HTA</span>, <span class=\"kw-bio\">INR</span> si <span class=\"kw-ttt\">anticoagulant</span>, anomalie vasculaire locale</li>\n                <li>Avec traumatisme : éliminer en <span class=\"kw-alerte\">urgence</span> une <strong>plaie de conjonctive/globe</strong> et un <strong>corps étranger intra-oculaire</strong> (<span class=\"kw-imagerie\">TDM</span> au moindre doute)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 247 — <span class=\"kw-def\">Diabète</span> et œil · 341 — HSA · obj-14 DR · obj-8 OVCR <span class=\"kw-etio\">ischémique</span></em></p>","frequence":3}],"astuces":[],"strategie":{"urgence":"<p><strong>OACR :</strong> <span class=\"kw-alerte\">urgence absolue</span>, c'est un <span class=\"kw-etio\">AVC rétinien</span> — lésions définitives dès <span class=\"kw-chiffre\">90 min</span>, fenêtre de reperméabilisation <span class=\"kw-chiffre\">≤ 6 h</span> ; <span class=\"kw-ttt\">aspirine</span> + orientation <span class=\"kw-ttt\">unité neurovasculaire</span> sans délai.<br><strong>NOIAA artéritique :</strong> devant toute suspicion de <span class=\"kw-etio\">maladie de Horton</span>, <span class=\"kw-ttt\">corticothérapie</span> débutée <span class=\"kw-alerte\">immédiatement</span>, avant la <span class=\"kw-ttt\">biopsie d'artère temporale</span> (risque de <span class=\"kw-alerte\">cécité bilatérale définitive</span>).<br><strong>Décollement de rétine :</strong> <span class=\"kw-def\">semi-urgence</span> chirurgicale — <span class=\"kw-ttt\">chirurgie</span> <span class=\"kw-chiffre\">< 1 semaine</span> si macula décollée, encore plus urgente si macula à plat.<br><strong>Amaurose fugace / CMT :</strong> <span class=\"kw-alerte\">urgence diagnostique</span> (<span class=\"kw-etio\">AIT rétinien</span>) — <span class=\"kw-imagerie\">imagerie des vaisseaux du cou</span> en urgence.</p>","hospit":"<p><strong>OACR :</strong> <span class=\"kw-alerte\">hospitalisation en unité neurovasculaire</span> (prise en charge d'un <span class=\"kw-etio\">AVC</span>) ; bilan étiologique et traitement menés dans le même temps.<br><strong>BAV brutale + œil blanc indolore :</strong> <span class=\"kw-clinique\">avis ophtalmologique urgent</span> avec <span class=\"kw-imagerie\">fond d'œil</span> systématique.<br><strong>Suspicion de Horton :</strong> <span class=\"kw-bio\">NFS-VS-CRP</span> en <span class=\"kw-alerte\">urgence</span> et <span class=\"kw-ttt\">corticothérapie</span> sans attendre la <span class=\"kw-ttt\">biopsie</span>.<br><strong>Trouble binoculaire brutal :</strong> <span class=\"kw-imagerie\">imagerie cérébrale</span> en urgence (suspicion d'<span class=\"kw-etio\">AVC</span>).</p>","redflags":"<ul><li><span class=\"kw-clinique\">BAV brutale</span> sur <span class=\"kw-clinique\">œil blanc indolore</span> : impose la recherche d'une <span class=\"kw-alerte\">urgence</span> (<span class=\"kw-etio\">OACR</span>, <span class=\"kw-etio\">NOIAA</span>, <span class=\"kw-etio\">décollement de rétine</span>)</li><li><span class=\"kw-radio\">Tache rouge cerise de la macula</span> avec <span class=\"kw-clinique\">acuité effondrée</span> → <span class=\"kw-etio\">OACR</span></li><li><span class=\"kw-clinique\">Amaurose fugace</span> (cécité monoculaire transitoire) → <span class=\"kw-etio\">AIT rétinien</span>, risque d'<span class=\"kw-alerte\">OACR ou d'AVC constitué</span></li><li>Après <span class=\"kw-chiffre\">50 ans</span> : <span class=\"kw-clinique\">céphalées</span> et signes de <span class=\"kw-etio\">Horton</span> + BAV → <span class=\"kw-etio\">NOIAA artéritique</span>, risque de <span class=\"kw-alerte\">bilatéralisation</span></li><li><span class=\"kw-clinique\">Myodésopsies</span> + <span class=\"kw-clinique\">phosphènes</span> + <span class=\"kw-clinique\">amputation du champ visuel périphérique</span> → <span class=\"kw-etio\">décollement de rétine</span></li><li><span class=\"kw-radio\">Œdème papillaire bilatéral</span> + <span class=\"kw-clinique\">céphalées et vomissements</span> → <span class=\"kw-etio\">HTIC</span>, imagerie cérébrale urgente</li><li><span class=\"kw-clinique\">Œil rouge douloureux</span> + BAV → <span class=\"kw-etio\">glaucome aigu</span>, <span class=\"kw-etio\">kératite</span>, <span class=\"kw-etio\">uvéite</span> ou <span class=\"kw-etio\">endophtalmie</span></li></ul>","principes":"<p>La prise en charge dépend de l'étiologie identifiée au <span class=\"kw-imagerie\">fond d'œil</span> ; <span class=\"kw-clinique\">les</span> urgences (<span class=\"kw-etio\">OACR</span>, <span class=\"kw-etio\">NOIAA artéritique</span>) imposent un traitement <span class=\"kw-alerte\">immédiat</span>.</p><p><strong>OACR (occlusion de l'artère centrale)</strong></p><p>Orientation en <span class=\"kw-ttt\">unité neurovasculaire</span> (prise en charge d'un <span class=\"kw-etio\">AVC</span>)</p><ul><li><span class=\"kw-ttt\">Aspirine</span> per os ou IV dans tous <span class=\"kw-clinique\">les</span> cas</li><li>Reperméabilisation maximale (<span class=\"kw-ttt\">acétazolamide / Diamox</span>, <span class=\"kw-ttt\">vasodilatateurs IV</span>, <span class=\"kw-ttt\">fibrinolytiques</span>) si <span class=\"kw-clinique\">sujet jeune</span> en bon état général, vu <span class=\"kw-chiffre\">< 6 h</span></li><li>Bilan étiologique parallèle : <span class=\"kw-imagerie\">échodoppler des TSA</span>, <span class=\"kw-imagerie\">échocardiographie</span>, <span class=\"kw-clinique\">Holter-ECG</span></li></ul><p><strong>NOIAA artéritique (maladie de Horton)</strong></p><p>Objectif : prévenir la <span class=\"kw-alerte\">bilatéralisation</span> et la cécité définitive</p><ul><li><span class=\"kw-bio\">NFS-VS-CRP</span> en urgence devant tout tableau évocateur</li><li><span class=\"kw-ttt\">Corticothérapie</span> immédiate : <span class=\"kw-ttt\">bolus de méthylprednisolone</span> relayés per os, ou <span class=\"kw-ttt\">prednisone</span> per os <span class=\"kw-chiffre\">1 mg/kg/j</span></li><li>Débuter <span class=\"kw-alerte\">avant la biopsie d'artère temporale</span> ; décroissance lente sur <span class=\"kw-chiffre\">18 à 24 mois</span></li><li><span class=\"kw-ttt\">Aspirine</span> à dose antiagrégante associée</li></ul><p><strong>Occlusions veineuses (OVCR / OBVR)</strong></p><p><span class=\"kw-ci\">Anti-VEGF déconseillés en cas d'événement cardiovasculaire récent</span></p><ul><li>Aucun <span class=\"kw-ttt\">traitement systémique</span> n'a prouvé son efficacité</li><li><span class=\"kw-ttt\">Anti-VEGF</span> ou <span class=\"kw-ttt\">implant de dexaméthasone</span> intravitréens si <span class=\"kw-radio\">œdème maculaire</span> avec BAV</li><li><span class=\"kw-ttt\">Photocoagulation panrétinienne (PPR) au laser argon</span> dans les <span class=\"kw-etio\">formes ischémiques</span> (prévention du <span class=\"kw-etio\">glaucome néovasculaire</span>)</li></ul><p><strong>Décollement de rétine rhegmatogène</strong></p><p>Pronostic d'autant meilleur que la chirurgie est <span class=\"kw-clinique\">précoce</span>, macula non encore soulevée</p><ul><li>Traitement curatif <span class=\"kw-ttt\">uniquement chirurgical</span> : <span class=\"kw-ttt\">cryothérapie-indentation</span> ou <span class=\"kw-ttt\">vitrectomie-laser-gaz / silicone</span></li><li>Regard du patient positionné <span class=\"kw-clinique\">vers le bas</span> en attendant le bloc</li><li><span class=\"kw-ttt\">Photocoagulation préventive au laser argon</span> sur les déhiscences à risque / l'œil controlatéral</li></ul>","suivi":"<p><strong>OVCR non <span class=\"kw-etio\">ischémique</span> :</strong> <span class=\"kw-imagerie\">surveillance clinique et angiographique</span> mensuelle pour dépister la <span class=\"kw-alerte\">conversion vers une forme ischémique</span>.<br><strong>NOIAA :</strong> pas de <span class=\"kw-clinique\">récupération visuelle</span> attendue ; <span class=\"kw-def\">surveillance</span> du risque de <span class=\"kw-alerte\">bilatéralisation</span> (<span class=\"kw-ttt\">corticothérapie</span> prolongée si Horton).<br><strong>Neuropathie optique aux antituberculeux</strong> (<span class=\"kw-ttt\">isoniazide</span>, <span class=\"kw-ttt\">éthambutol</span>) : <span class=\"kw-imagerie\">champ visuel + vision des couleurs + OCT</span> avant traitement, à <span class=\"kw-chiffre\">J21</span>, <span class=\"kw-chiffre\">M2</span>, puis tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">2 mois</span>.</p>"},"liensGlobaux":[{"href":"https://www.cen-neurologie.fr/second-cycle/alteration-aigue-de-la-vision","label":"Collège CEN — Altération aiguë de la vision"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"BAV brutale récente — Altération aiguë de la vision","detail":"<h4>CAT — Baisse de vision brutale (œil blanc) et identification des urgences — Démarche d'orientation devant une altération aiguë de la vision</h4>","branches":[{"to":"q-mono","label":"BAV brutale","color":"blue"}]},{"id":"q-mono","kind":"decision","label":"Trouble mono- ou binoculaire ? — Cacher alternativement chaque œil","branches":[{"to":"t-binoc","label":"Binoculaire","color":"red"},{"to":"q-rouge","label":"Monoculaire","color":"blue"}]},{"id":"t-binoc","kind":"terminal","label":"Atteinte cérébrale / rétrochiasmatique","color":"red","detail":"<h4>Clinique</h4><ul><li>Déficit binoculaire : <span class=\"kw-etio\">hémianopsie latérale homonyme</span>, <span class=\"kw-etio\">quadranopsie</span> ou <span class=\"kw-etio\">cécité corticale</span></li><li>Cécité corticale : <span class=\"kw-clinique\">réflexe photomoteur conservé</span> et <span class=\"kw-imagerie\">fond d'œil normal</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-imagerie\">Imagerie cérébrale</span> en <span class=\"kw-alerte\">urgence</span> — suspicion d'<span class=\"kw-etio\">AVC</span> (territoire vertébrobasilaire)</li></ul>"},{"id":"q-rouge","kind":"decision","label":"Œil rouge et/ou douloureux ?","branches":[{"to":"t-rouge","label":"Oui — œil rouge ± douleur","color":"red"},{"to":"q-fo","label":"Non — œil blanc indolore","color":"blue"}]},{"id":"t-rouge","kind":"terminal","label":"Avis ophtalmologique urgent","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-etio\">Glaucome aigu par fermeture de l'angle</span>, <span class=\"kw-etio\">kératite</span>, <span class=\"kw-etio\">uvéite antérieure</span>, <span class=\"kw-etio\">endophtalmie</span>, <span class=\"kw-etio\">glaucome néovasculaire</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-clinique\">Avis ophtalmologique urgent</span> ; <span class=\"kw-ci\">pas de corticoïdes locaux sans diagnostic précis</span> (risque sur kératite)</li></ul>"},{"id":"q-fo","kind":"decision","label":"Fond d'œil en urgence — aspect ? — Œil blanc indolore + BAV unilatérale","branches":[{"to":"t-hiv","label":"FO non visible","color":"amber"},{"to":"t-norb","label":"FO normal","color":"amber"},{"to":"t-oacr","label":"Tache rouge cerise, AV effondrée","color":"red"},{"to":"t-noiaa","label":"Œdème papillaire pâle, déficit altitudinal","color":"red"},{"to":"t-ovcr","label":"Hémorragies des 4 quadrants, veines dilatées","color":"amber"},{"to":"t-dr","label":"Rétine soulevée en relief, déhiscence","color":"amber"}]},{"id":"t-hiv","kind":"terminal","label":"Hémorragie intravitréenne","color":"amber","detail":"<h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">Échographie B</span> systématique quand la rétine n'est pas visible, pour <span class=\"kw-alerte\">éliminer un décollement de rétine</span> sous-jacent</li></ul><h4>Clinique</h4><ul><li>Prodrome en « <span class=\"kw-clinique\">pluie de suie</span> » ; causes : <span class=\"kw-etio\">rétinopathie diabétique proliférante</span>, <span class=\"kw-etio\">déchirure rétinienne</span>, <span class=\"kw-etio\">syndrome de Terson</span></li></ul>"},{"id":"t-norb","kind":"terminal","label":"Neuropathie optique rétrobulbaire / voies optiques","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Scotome central ou cæcocentral</span> ; contexte de <span class=\"kw-etio\">SEP</span> évocateur</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">IRM des nerfs optiques</span> ± <span class=\"kw-imagerie\">IRM cérébrale</span>, <span class=\"kw-imagerie\">PEV</span></li></ul>"},{"id":"t-oacr","kind":"terminal","label":"OACR — urgence (AVC rétinien)","color":"red","detail":"<h4>Délai</h4><ul><li>Lésions définitives dès <span class=\"kw-chiffre\">90 min</span> ; fenêtre de reperméabilisation <span class=\"kw-chiffre\">≤ 6 h</span></li></ul><h4>Clinique</h4><ul><li><span class=\"kw-clinique\">BAV brutale profonde</span>, <span class=\"kw-clinique\">mydriase aréflective</span>, <span class=\"kw-clinique\">RPM direct aboli</span></li><li><span class=\"kw-imagerie\">FO</span> : <span class=\"kw-radio\">œdème ischémique blanchâtre</span> + <span class=\"kw-radio\">tache rouge cerise de la macula</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Aspirine</span> ; <span class=\"kw-alerte\">hospitalisation</span> en <span class=\"kw-ttt\">unité neurovasculaire</span></li><li>Reperméabilisation (<span class=\"kw-ttt\">Diamox</span>, <span class=\"kw-ttt\">vasodilatateurs IV</span>, <span class=\"kw-ttt\">fibrinolytiques</span>) si <span class=\"kw-clinique\">sujet jeune</span> vu <span class=\"kw-chiffre\">< 6 h</span></li></ul>"},{"id":"t-noiaa","kind":"terminal","label":"NOIAA — éliminer une maladie de Horton","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-imagerie\">FO</span> : <span class=\"kw-radio\">œdème papillaire pâle</span>, <span class=\"kw-radio\">hémorragies en flammèches</span> ; <span class=\"kw-clinique\">déficit altitudinal</span>, <span class=\"kw-clinique\">signe de Marcus Gunn</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">NFS-VS-CRP</span> en <span class=\"kw-alerte\">urgence</span> ; <span class=\"kw-ttt\">biopsie d'artère temporale</span> (sans retarder le traitement)</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Corticothérapie</span> immédiate (<span class=\"kw-ttt\">bolus de méthylprednisolone</span> ou <span class=\"kw-ttt\">prednisone</span> <span class=\"kw-chiffre\">1 mg/kg/j</span>), avant la <span class=\"kw-ttt\">biopsie</span> + <span class=\"kw-ttt\">aspirine</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Risque de <span class=\"kw-alerte\">cécité bilatérale définitive</span> ; pas de récupération visuelle attendue</li></ul>"},{"id":"t-ovcr","kind":"terminal","label":"OVCR (occlusion veineuse)","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-imagerie\">FO</span> : <span class=\"kw-radio\">veines tortueuses et dilatées</span>, <span class=\"kw-radio\">hémorragies disséminées</span> (4 quadrants), <span class=\"kw-radio\">œdème maculaire</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Anti-VEGF</span> ou <span class=\"kw-ttt\">dexaméthasone</span> intravitréens si <span class=\"kw-radio\">œdème maculaire</span> ; <span class=\"kw-ttt\">PPR</span> si <span class=\"kw-etio\">forme ischémique</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-imagerie\">Surveillance angiographique</span> mensuelle : dépister la <span class=\"kw-alerte\">conversion ischémique</span> et le <span class=\"kw-etio\">glaucome néovasculaire</span></li></ul>"},{"id":"t-dr","kind":"terminal","label":"Décollement de rétine — chirurgie rapide","color":"amber","detail":"<h4>Délai</h4><ul><li><span class=\"kw-def\">Semi-urgence</span> : <span class=\"kw-ttt\">chirurgie</span> <span class=\"kw-chiffre\">< 1 semaine</span> si macula décollée, plus urgente si macula encore à plat</li></ul><h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Myodésopsies</span>, <span class=\"kw-clinique\">phosphènes</span>, <span class=\"kw-clinique\">amputation du champ visuel</span> ; <span class=\"kw-imagerie\">FO</span> : <span class=\"kw-radio\">rétine en relief, mobile, avec déhiscence</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Chirurgie</span> (<span class=\"kw-ttt\">cryo-indentation</span> ou <span class=\"kw-ttt\">vitrectomie-laser-gaz</span>) ; regard <span class=\"kw-clinique\">vers le bas</span> en attendant le bloc</li></ul>"}]},"cards":[{"i":"505a16758a8e","n":82,"o":"82-1","u":"Diagnostic positif","t":"Savoir déterminer si un trouble visuel est mono- ou binoculaire","q":"Comment différencier un trouble visuel aigu monoculaire d'un trouble binoculaire lors de l'examen clinique initial ?","a":"<p>Pour différencier un trouble visuel monoculaire d'un binoculaire, il faut demander au patient de <strong>boucher alternativement chaque œil</strong>. Si le trouble persiste à un œil et disparaît à l'autre (l'œil non atteint), le trouble est <strong>monoculaire</strong>.</p>"},{"i":"65bce255c6d2","n":82,"o":"82-1","u":"Diagnostic positif","t":"Savoir déterminer si un trouble visuel est mono- ou binoculaire","q":"Quelle est la principale orientation diagnostique devant un trouble visuel aigu <em>monoculaire</em> ?","a":"<p>Un trouble visuel aigu <strong>monoculaire</strong> oriente principalement vers une atteinte <strong>pré-chiasmatique</strong>. Cela signifie une lésion du <strong>globe oculaire</strong> (rétine, vitré, etc.) ou du <strong>nerf optique</strong>. Une atteinte de la partie latérale du chiasma est une cause plus rare mais possible.</p>"},{"i":"eed2e15a17ea","n":82,"o":"82-1","u":"Diagnostic positif","t":"Savoir déterminer si un trouble visuel est mono- ou binoculaire","q":"Quelle est la principale orientation diagnostique devant un trouble visuel aigu <em>binoculaire</em> ?","a":"<p>Un trouble visuel aigu <strong>binoculaire</strong> oriente le plus souvent vers une <strong>atteinte cérébrale</strong>. Il s'agit généralement d'une lésion du <strong>chiasma</strong> ou des <strong>voies visuelles rétrochiasmatiques</strong> (lobe temporal, pariétal, occipital). Une atteinte bilatérale du globe oculaire ou des nerfs optiques est également possible mais plus rare.</p>"},{"i":"3acc42e6abbb","n":82,"o":"82-11","u":"Diagnostic positif","t":"Savoir évoquer le diagnostic d’aura migraineuse","q":"Quel est l'intérêt des examens complémentaires, notamment l'IRM cérébrale, dans le diagnostic d'une aura migraineuse visuelle ?","a":"<p>En cas de tableau clinique <strong>typiques</strong>, <strong>aucun</strong> examen complémentaire n'est nécessaire. Une <strong>IRM cérébrale</strong> est indiquée uniquement en cas d'<strong>atypies</strong> telles que :</p><ul><li>Un âge tardif de début.</li><li>Une durée inhabituelle.</li><li>Une fréquence ou une chronologie des crises atypiques.</li></ul>"},{"i":"63254bee7590","n":82,"o":"82-11","u":"Diagnostic positif","t":"Savoir évoquer le diagnostic d’aura migraineuse","q":"Quels sont les critères diagnostiques cliniques permettant d'évoquer une aura migraineuse visuelle typique ?","a":"<ul><li>Le caractère <strong>récidivant</strong> des épisodes, souvent depuis l'enfance ou l'adolescence.</li><li>La <strong>normalité</strong> de l'examen neurologique et ophtalmologique après la crise.</li></ul>"},{"i":"9cfa39d97c01","n":82,"o":"82-11","u":"Diagnostic positif","t":"Savoir évoquer le diagnostic d’aura migraineuse","q":"Quelle est la durée typique de l'aura migraineuse visuelle et ce qui lui succède ?","a":"<p>L'aura migraineuse visuelle régresse en <strong>15 à 20 minutes</strong>. Elle est classiquement suivie d'une <strong>céphalée pulsatile</strong>, souvent hémicrânienne et controlatérale, bien qu'une aura sans céphalée soit possible ('aura sans céphalée').</p>"},{"i":"c0119b212e8a","n":82,"o":"82-11","u":"Diagnostic positif","t":"Savoir évoquer le diagnostic d’aura migraineuse","q":"Comment définir l'aura migraineuse visuelle, notamment en termes de population affectée et de fréquence ?","a":"<p>L'aura migraineuse visuelle est une cause <strong>fréquente</strong> de trouble visuel <strong>binoculaire transitoire</strong>, survenant typiquement chez l'<strong>adulte jeune</strong>.</p>"},{"i":"f25369428530","n":82,"o":"82-11","u":"Diagnostic positif","t":"Savoir évoquer le diagnostic d’aura migraineuse","q":"Quelles sont les manifestations cliniques caractéristiques du scotome scintillant dans l'aura migraineuse visuelle ?","a":"<ul><li><strong>Flou visuel bilatéral</strong> avec <strong>flashs colorés</strong>.</li><li>Présence d'un <strong>scotome scintillant</strong> qui <strong>s'étend progressivement</strong> (généralement du centre vers la périphérie ou inversement) en quelques minutes.</li><li>Ce scotome affecte un <strong>hémichamp homonyme</strong> (hémianopsie latérale homonyme - HLH) ou l'ensemble du champ visuel.</li></ul>"},{"i":"1030cf982ec0","n":82,"o":"82-15","u":"Identifier une urgence","t":"Savoir évoquer un décollement de rétine","q":"Quelle est la conduite à tenir en urgence diagnostique face à une suspicion de décollement de rétine (DR) ?","a":"<p>Il faut réaliser en urgence un <strong>fond d'œil dilaté</strong>. Celui-ci met en évidence une rétine en relief, mobile, formant des plis, et éventuellement la déhiscence (déchirure) visible. Si le fond d'œil n'est pas possible (par exemple, en cas d'hémorragie du vitré associée), une <strong>échographie B systématique</strong> doit être pratiquée pour rechercher le DR sous-jacent.</p>"},{"i":"2213c19d7155","n":82,"o":"82-15","u":"Identifier une urgence","t":"Savoir évoquer un décollement de rétine","q":"Quels sont les quatre signes fonctionnels composant la tétrade clinique évocatrice d'un décollement de rétine (DR) rhegmatogène, et quel est leur substrat physiopathologique ?","a":"<ul><li><strong>Myodésopsies</strong> (« mouches volantes ») : traduisent le décollement du vitré postérieur (première étape).</li><li><strong>Phosphènes</strong> (éclairs/flashs fixes, continus) : signalent la survenue d'une déchirure rétinienne par stimulation des récepteurs à l'endroit de la traction.</li><li><strong>Amputation du champ visuel périphérique</strong> : correspond à la constitution du DR. Elle est classiquement opposée au décollement (par exemple, un DR au pôle supérieur entraîne une amputation du CV inférieur).</li><li><strong>Baisse de l'acuité visuelle</strong> (BAV) : survient en cas de soulèvement de la macula par le DR et est un signe de <strong>mauvais pronostic</strong>.</li></ul>"},{"i":"2234da4af8f9","n":82,"o":"82-15","u":"Identifier une urgence","t":"Savoir évoquer un décollement de rétine","q":"Quelle est la définition d'un décollement de rétine (DR) rhegmatogène et pourquoi constitue-t-il une urgence ophtalmologique ?","a":"<p>Le décollement de rétine rhegmatogène est une <strong>pathologie ophtalmologique urgente</strong> caractérisée par la séparation des couches de la rétine. Sans traitement, il évolue inexorablement vers la <strong>cécité</strong> par <strong>destruction irréversible des photorécepteurs</strong>.</p>"},{"i":"411aa0b5f98d","n":82,"o":"82-15","u":"Identifier une urgence","t":"Savoir évoquer un décollement de rétine","q":"Quels sont les principaux facteurs de risque à rechercher lors de l'évocation d'un décollement de rétine (DR) ?","a":"<ul><li><strong>Myopie forte</strong> (> –6 Dioptries).</li><li>Antécédents de <strong>chirurgie de la cataracte</strong>.</li><li><strong>Traumatisme oculaire</strong>.</li><li>Antécédents personnels ou familiaux de DR.</li></ul>"},{"i":"9bc5a67aa117","n":82,"o":"82-15","u":"Identifier une urgence","t":"Savoir évoquer un décollement de rétine","q":"Quelle est la prise en charge thérapeutique d'un décollement de rétine (DR) et les délais de traitement ?","a":"<p>Le traitement est <strong>uniquement chirurgical</strong>. Le délai est un facteur pronostique important : il doit être inférieur à <strong>une semaine</strong> si la macula est soulevée, et encore plus urgent si la macula est « à plat » (non encore décollée). Dans l'attente de la chirurgie, il est souvent recommandé de positionner le regard du patient vers le bas pour limiter l'extension du DR.</p>"},{"i":"0063a52c59fb","n":82,"o":"82-2","u":"Définition","t":"Connaître la définition, la signification, et la démarche étiologique devant une cécité monoculaire transitoire","q":"Quelles sont les principales étiologies à rechercher en urgence devant une cécité monoculaire transitoire (CMT) ?","a":"<p>Les principales étiologies sont :</p><ul><li>un <strong>athérome carotidien</strong></li><li>une <strong>cardiopathie emboligène</strong></li><li>une <strong>maladie de Horton</strong> (à évoquer systématiquement après 50 ans)</li></ul>"},{"i":"06f34df3737b","n":82,"o":"82-2","u":"Définition","t":"Connaître la définition, la signification, et la démarche étiologique devant une cécité monoculaire transitoire","q":"Quelle est la définition de la cécité monoculaire transitoire (CMT) ou amaurose fugace ?","a":"<p>La cécité monoculaire transitoire est une disparition <strong>totale de la vision</strong> (ou flou visuel, ou amputation du champ visuel) d'un seul œil, durant <strong>quelques minutes à quelques heures</strong> (habituellement < 10 min), et se résolvant spontanément.</p>"},{"i":"07e052f5c4ad","n":82,"o":"82-2","u":"Définition","t":"Connaître la définition, la signification, et la démarche étiologique devant une cécité monoculaire transitoire","q":"Quelle est la signification clinique de la cécité monoculaire transitoire (CMT) ?","a":"<p>La cécité monoculaire transitoire est considérée comme l'<strong>équivalent rétinien d'un accident ischémique transitoire (AIT)</strong>, le plus souvent d'origine embolique.</p>"},{"i":"5d4a324328eb","n":82,"o":"82-2","u":"Définition","t":"Connaître la définition, la signification, et la démarche étiologique devant une cécité monoculaire transitoire","q":"Quelle est la démarche diagnostique urgente devant une suspicion d'athérome carotidien comme cause de cécité monoculaire transitoire (CMT) ?","a":"<p>Il faut réaliser en urgence une <strong>imagerie des vaisseaux du cou</strong> : <strong>écho-Doppler</strong>, <strong>angio-IRM</strong> ou <strong>angio-TDM des TSAO</strong> (Troncs Supra-Aortiques).</p>"},{"i":"89c64e2ab4d0","n":82,"o":"82-2","u":"Définition","t":"Connaître la définition, la signification, et la démarche étiologique devant une cécité monoculaire transitoire","q":"Pourquoi la cécité monoculaire transitoire (CMT) est-elle une urgence diagnostique ?","a":"<p>La cécité monoculaire transitoire est une <strong>urgence diagnostique majeure</strong> car elle fait courir le risque d'une <strong>occlusion de l'artère centrale de la rétine (OACR) constituée</strong> ou d'un <strong>accident vasculaire cérébral (AVC) ischémique</strong>.</p>"},{"i":"933040cb927c","n":82,"o":"82-2","u":"Définition","t":"Connaître la définition, la signification, et la démarche étiologique devant une cécité monoculaire transitoire","q":"Quelle est la démarche diagnostique urgente devant une suspicion de maladie de Horton comme cause de cécité monoculaire transitoire (CMT) ?","a":"<p>Il faut doser en urgence la <strong>VS</strong> (Vitesse de Sédimentation) et la <strong>CRP</strong> (Protéine C Réactive). Une <strong>corticothérapie</strong> doit être débutée sans délai si la suspicion est forte.</p>"},{"i":"9748ad627728","n":82,"o":"82-2","u":"Définition","t":"Connaître la définition, la signification, et la démarche étiologique devant une cécité monoculaire transitoire","q":"Quelle est la démarche diagnostique urgente devant une suspicion de cardiopathie emboligène comme cause de cécité monoculaire transitoire (CMT) ?","a":"<p>Il faut réaliser un <strong>ECG</strong>, une <strong>échocardiographie</strong> et un <strong>Holter-ECG</strong>.</p>"},{"i":"b0238eec478b","n":82,"o":"82-2","u":"Définition","t":"Connaître la définition, la signification, et la démarche étiologique devant une cécité monoculaire transitoire","q":"Quels éléments rechercher au fond d'œil devant une cécité monoculaire transitoire (CMT) ?","a":"<p>Le fond d'œil peut révéler la présence d'<strong>emboles de cholestérol</strong> au niveau des bifurcations artérielles, bien que rares, ils sont <strong>pathognomoniques</strong> de l'origine embolique.</p>"},{"i":"bbf2420cde28","n":82,"o":"82-2","u":"Définition","t":"Connaître la définition, la signification, et la démarche étiologique devant une cécité monoculaire transitoire","q":"Quel est un piège classique concernant la cécité monoculaire transitoire (CMT) et la maladie de Horton ?","a":"<p>Une cécité monoculaire transitoire peut être la <strong>première manifestation d'une maladie de Horton</strong> chez le sujet de <strong>plus de 50 ans</strong>. Il faut <strong>toujours doser la VS et la CRP</strong> même devant un épisode unique et bref de cécité monoculaire transitoire chez ce type de patient.</p>"},{"i":"e08757519884","n":82,"o":"82-2","u":"Définition","t":"Connaître la définition, la signification, et la démarche étiologique devant une cécité monoculaire transitoire","q":"Quels sont les signes associés possibles à une cécité monoculaire transitoire (CMT) ?","a":"<p>Bien que le plus souvent isolée, une cécité monoculaire transitoire peut s'associer à des <strong>signes neurologiques controlatéraux</strong>, définissant un <strong>syndrome opticopyramidal</strong> (cécité monoculaire transitoire du côté de la lésion et hémiparésie controlatérale).</p>"},{"i":"30e06e2a2e5c","n":82,"o":"82-3","u":"Diagnostic positif","t":"Savoir interpréter un réflexe photomoteur direct et consensuel (voir item 81)","q":"Qu'est-ce que le signe de Marcus Gunn et à quelles pathologies est-il associé en cas d'altération aiguë de la vision ?","a":"<p>Le <strong>signe de Marcus Gunn</strong> (ou déficit pupillaire afférent relatif) se caractérise par un <strong>RPM diminué à l'éclairement de l'œil atteint</strong>, alors que le RPM consensuel est conservé à l'éclairement de l'œil sain. Il est classiquement associé à la <strong>névrite optique ischémique antérieure aiguë (NOIA)</strong> ou à la <strong>névrite optique rétrobulbaire (NORB)</strong>, des atteintes du nerf optique.</p>"},{"i":"5d66c3303646","n":82,"o":"82-3","u":"Diagnostic positif","t":"Savoir interpréter un réflexe photomoteur direct et consensuel (voir item 81)","q":"Quelle est l'interprétation d'un réflexe photomoteur (RPM) direct aboli mais un RPM consensuel conservé à l'éclairement de l'œil atteint ?","a":"<p>Un <strong>RPM direct aboli à l'éclairement de l'œil atteint</strong>, mais un <strong>RPM consensuel conservé à l'éclairement de l'œil controlatéral sain</strong>, est en faveur d'une pathologie sévère affectant le capteur sensoriel de l'œil éclairé, telle qu'une <strong>occlusion de l'artère centrale de la rétine (OACR)</strong> ou une <strong>atteinte sévère du nerf optique pré-chiasmatique</strong>.</p>"},{"i":"8ab57c41e1ac","n":82,"o":"82-3","u":"Diagnostic positif","t":"Savoir interpréter un réflexe photomoteur direct et consensuel (voir item 81)","q":"Comment distinguer une atteinte du capteur sensoriel d'une atteinte centrale de la vision par l'examen du réflexe photomoteur (RPM) ?","a":"<p>Le réflexe photomoteur permet de différencier ces atteintes car il évalue la voie afférente (rétine, nerf optique pré-chiasmatique) et la voie efférente. En cas d'atteinte du capteur sensoriel, le RPM est altéré, tandis qu'en cas de cécité corticale (atteinte centrale), il est conservé.</p>"},{"i":"ce38d1149922","n":82,"o":"82-3","u":"Diagnostic positif","t":"Savoir interpréter un réflexe photomoteur direct et consensuel (voir item 81)","q":"Quelle est la particularité du réflexe photomoteur (RPM) en cas de cécité corticale bilatérale aiguë ?","a":"<p>En cas de cécité corticale bilatérale aiguë, le <strong>réflexe photomoteur (RPM) direct et consensuel est conservé</strong>. Ceci est une notion clé, car il permet de distinguer cette atteinte centrale (lésion des lobes occipitaux, souvent par <strong>AVC vertébrobasilaire</strong>) des causes de cécité liées à une atteinte du capteur sensoriel.</p>"},{"i":"1549ed59a7e7","n":82,"o":"82-4","u":"Contenu multimédia","t":"Interpréter un réflexe photomoteur direct et consensuel (voir item 81)","q":"Quel est le piège diagnostique clinique concernant le réflexe photomoteur dans le contexte d'une altération aiguë de la vision ?","a":"<p>Un piège diagnostique classique est la présence d'une <strong>mydriase aréflective unilatérale</strong> accompagnée d'une <strong>baisse d'acuité visuelle brutale</strong> et d'un <strong>œil blanc indolore</strong>. Cette présentation doit faire évoquer une <strong>occlusion de l'artère centrale de la rétine (OACR)</strong> jusqu'à preuve du contraire et impose la réalisation d'un <strong>fond d'œil en urgence</strong>.</p>"},{"i":"4991cc312142","n":82,"o":"82-4","u":"Contenu multimédia","t":"Interpréter un réflexe photomoteur direct et consensuel (voir item 81)","q":"Comment se comportent les réflexes photomoteurs en cas de cécité corticale ?","a":"<p>En cas de cécité corticale, les RPM direct et consensuel sont <strong>conservés bilatéralement</strong>. Cela indique que le capteur sensoriel (la rétine) est intact, mais qu'il y a une absence d'interprétation corticale du signal visuel, souvent due à un accident vasculaire cérébral vertébrobasilaire.</p>"},{"i":"abf157c75056","n":82,"o":"82-4","u":"Contenu multimédia","t":"Interpréter un réflexe photomoteur direct et consensuel (voir item 81)","q":"Quelle est la manœuvre clinique clé pour interpréter les réflexes photomoteurs (RPM) lors d'une altération aiguë de la vision ?","a":"<p>La manœuvre clé est le <strong><em>swinging flashlight test</em></strong>, qui consiste à comparer systématiquement le RPM direct et consensuel en éclairant chaque œil alternativement.</p>"},{"i":"ef70edcb0525","n":82,"o":"82-4","u":"Contenu multimédia","t":"Interpréter un réflexe photomoteur direct et consensuel (voir item 81)","q":"Comment se manifeste le réflexe photomoteur dans le cas d'une occlusion de l'artère centrale de la rétine (OACR) aiguë ?","a":"<p>Dans le cas d'une OACR aiguë, le RPM direct est <strong>aboli</strong> au niveau de l'œil atteint et le RPM consensuel est <strong>conservé</strong> lorsque l'on éclaire l'œil sain. Cela se traduit par une <strong>mydriase aréflective</strong> dès les premières minutes.</p>"},{"i":"fdce8c0319df","n":82,"o":"82-4","u":"Contenu multimédia","t":"Interpréter un réflexe photomoteur direct et consensuel (voir item 81)","q":"Quel est le signe pupillaire caractéristique d'une neuropathie optique ischémique antérieure (NOIA) aiguë et que signifie-t-il ?","a":"<p>Le signe caractéristique est le <strong>Signe de Marcus Gunn</strong>. Il se manifeste par une <strong>asymétrie</strong> avec une diminution du RPM direct à l'éclairement de l'œil atteint, tandis que le RPM consensuel est conservé. Il témoigne d'une <strong>atteinte partielle du nerf optique antérieur</strong>, correspondant à un déficit pupillaire afférent relatif.</p>"},{"i":"33d6ce4a68ab","n":82,"o":"82-6","u":"Étiologies","t":"Connaître les principales causes d’atteinte des voies optiques et du nerf optique et identifier les étiologies nécessitant une prise en charge urgente (névrite optique ischémique antérieure aiguë (NOIAA), œdème papillaire)","q":"Que doit faire évoquer une Névrite Optique RétroBulbaire (NORB) unilatérale chez un sujet jeune ?","a":"Une NORB unilatérale chez un sujet jeune doit faire évoquer en priorité une <strong>première poussée de sclérose en plaques (SEP)</strong>. Il faut rechercher d'autres signes neurologiques associés et indiquer la réalisation d'une <strong>IRM cérébro-médullaire</strong> pour étayer le diagnostic."},{"i":"3fb4ddf63f23","n":82,"o":"82-6","u":"Étiologies","t":"Connaître les principales causes d’atteinte des voies optiques et du nerf optique et identifier les étiologies nécessitant une prise en charge urgente (névrite optique ischémique antérieure aiguë (NOIAA), œdème papillaire)","q":"Quelle est l'attitude à adopter face à un œdème papillaire de stase par HTIC ?","a":"Un œdème papillaire de stase par Hypertension IntraCrânienne (HTIC) doit faire réaliser une <strong>imagerie cérébrale en urgence</strong>. L'objectif est de rechercher une cause sous-jacente comme une tumeur, une hémorragie, ou une thrombose veineuse cérébrale."},{"i":"5e43778b338e","n":82,"o":"82-6","u":"Étiologies","t":"Connaître les principales causes d’atteinte des voies optiques et du nerf optique et identifier les étiologies nécessitant une prise en charge urgente (névrite optique ischémique antérieure aiguë (NOIAA), œdème papillaire)","q":"Quelles sont les principales étiologies d'une atteinte du nerf optique (pré-chiasmatique) ?","a":"Les étiologies principales d'une atteinte pré-chiasmatique du nerf optique incluent :\n<ul>\n<li>La <strong>NOIAA</strong> (Névrite Optique Ischémique Antérieure Aiguë), notamment la forme artéritique par maladie de <strong>Horton</strong> qui est une urgence.</li>\n<li>La <strong>NORB</strong> (Névrite Optique RétroBulbaire), souvent associée à la <strong> SEP</strong>.</li>\n<li>L'<strong>œdème papillaire de stase</strong> lié à une HTIC.</li>\n<li>Les <strong>neuropathies optiques tumorales</strong> (gliome, méningiome de la gaine).</li>\n<li>Les <strong>neuropathies optiques toxiques/médicamenteuses</strong> (antituberculeux comme l'isoniazide, l'éthambutol, alcool-tabac, plomb).</li>\n<li>Les <strong>neuropathies optiques métaboliques</strong> (diabète).</li>\n<li>Les <strong>traumatismes</strong>.</li>\n</ul>"},{"i":"69c5ff99edbb","n":82,"o":"82-6","u":"Étiologies","t":"Connaître les principales causes d’atteinte des voies optiques et du nerf optique et identifier les étiologies nécessitant une prise en charge urgente (névrite optique ischémique antérieure aiguë (NOIAA), œdème papillaire)","q":"Quelles sont les principales étiologies d'une atteinte des voies rétrochiasmatiques (bandelettes, radiations, cortex) ?","a":"Les atteintes des voies rétrochiasmatiques peuvent être dues à :\n<ul>\n<li>Des causes <strong>vasculaires</strong> (AVC, hématome compressif) avec une installation brutale.</li>\n<li>Des causes <strong>tumorales</strong> avec une installation progressive.</li>\n<li>Des causes <strong>traumatiques</strong>, apparaissant contemporaines du traumatisme.</li>\n</ul>"},{"i":"c0bd3c22d05e","n":82,"o":"82-6","u":"Étiologies","t":"Connaître les principales causes d’atteinte des voies optiques et du nerf optique et identifier les étiologies nécessitant une prise en charge urgente (névrite optique ischémique antérieure aiguë (NOIAA), œdème papillaire)","q":"Quelle est l'attitude à adopter face à une Névrite Optique Ischémique Antérieure Aiguë (NOIAA) artéritique ?","a":"La NOIAA artéritique, le plus souvent due à la maladie de <strong>Horton</strong>, est une urgence devant le risque de <strong>bilatéralisation</strong> en quelques jours pouvant mener à une cécité bilatérale définitive. Elle justifie la mise en place immédiate d'une <strong>corticothérapie générale</strong>, sans attendre le résultat de la biopsie de l'artère temporale."},{"i":"c77ffad872c7","n":82,"o":"82-6","u":"Étiologies","t":"Connaître les principales causes d’atteinte des voies optiques et du nerf optique et identifier les étiologies nécessitant une prise en charge urgente (névrite optique ischémique antérieure aiguë (NOIAA), œdème papillaire)","q":"Quelles sont les principales étiologies d'une atteinte du chiasma optique ?","a":"Les principales étiologies d'une atteinte du chiasma optique entraînant souvent une <strong>hémianopsie bitemporale</strong> sont :\n<ul>\n<li>L'<strong>adénome hypophysaire</strong> (étiologie principale chez l'adulte).</li>\n<li>Chez l'adulte, également le méningiome du tubercule de la selle, l'anévrisme de la carotide interne, et le craniopharyngiome.</li>\n<li>Chez l'enfant, le <strong>gliome du chiasma</strong> (particulièrement en cas de <strong>NF1</strong>) et le craniopharyngiome.</li>\n</ul>"},{"i":"01cf83a4cb1e","n":82,"o":"82-7","u":"Identifier une urgence","t":"Connaître la conduite à tenir devant une baisse de vision brutale avec œil blanc et identification des urgences","q":"Quelle est la prise en charge chirurgicale d'un décollement de rétine ?","a":"<p>La chirurgie doit être réalisée en <strong>moins d'une semaine</strong>. L'urgence est encore plus grande si la macula est à plat (non décollée), ce qui permet de préserver son intégrité fonctionnelle. En cas de macula soulevée, l'urgence reste importante pour éviter l'aggravation de la BAV.</p>"},{"i":"0524b78bb1a0","n":82,"o":"82-7","u":"Identifier une urgence","t":"Connaître la conduite à tenir devant une baisse de vision brutale avec œil blanc et identification des urgences","q":"Quelle est la conduite à tenir immédiate face à une suspicion d'occlusion de l'artère centrale de la rétine (OACR) ?","a":"<p>C'est une <strong>urgence ophtalmologique majeure</strong>. L'hospitalisation en <strong>Unité Neuro-Vasculaire (UNV)</strong> est immédiate, une intervention dans la <strong>fenêtre des 6 heures</strong> est primordiale avec administration d'aspirine, de vasodilatateurs IV et de Diamox®, et possiblement une fibrinolyse.</p>"},{"i":"40c9d7a6caa1","n":82,"o":"82-7","u":"Identifier une urgence","t":"Connaître la conduite à tenir devant une baisse de vision brutale avec œil blanc et identification des urgences","q":"Quelle est la CAT devant une hémorragie du vitré diagnostiquée uniquement par l'anamnèse de 'pluie de suie' et un fond d'œil non visible ?","a":"<p>La CAT est la réalisation d'une <strong>échographie B systématique et urgente</strong> afin d'éliminer un décollement de rétine sous-jacent, qui constituerait alors une urgence thérapeutique absolue.</p>"},{"i":"50ab0348358a","n":82,"o":"82-7","u":"Identifier une urgence","t":"Connaître la conduite à tenir devant une baisse de vision brutale avec œil blanc et identification des urgences","q":"Quels diagnostics sont à évoquer devant une BAV brutale unilatérale, indolore, avec œil blanc et un FO NORMAL ?","a":"<ul><li>Une <strong>névrite optique rétrobulbaire (NORB)</strong> chez un sujet jeune, associée à une douleur à la mobilisation oculaire, un scotome central, et qui peut s'inscrire dans le contexte d'une SEP.</li><li>Des atteintes des <strong>voies optiques chiasmatiques et rétrochiasmatiques</strong>.</li></ul>"},{"i":"85f5f5ff12ef","n":82,"o":"82-7","u":"Identifier une urgence","t":"Connaître la conduite à tenir devant une baisse de vision brutale avec œil blanc et identification des urgences","q":"Quel diagnostic devez-vous évoquer en cas de BAV brutale unilatérale, indolore, avec œil blanc et FO NON visible ?","a":"<ul><li>Une <strong>uvéite intermédiaire</strong> (voire postérieure).</li><li>Une <strong>hémorragie intravitréenne</strong>, nécessitant une échographie B en urgence pour éliminer un décollement de rétine sous-jacent.</li></ul>"},{"i":"9ff5d93f681b","n":82,"o":"82-7","u":"Identifier une urgence","t":"Connaître la conduite à tenir devant une baisse de vision brutale avec œil blanc et identification des urgences","q":"Quelle est la prise en charge immédiate d'une neuropathie optique ischémique antérieure aiguë (NOIAA) artéritique suspectée (maladie de Horton) ?","a":"<p>Une <strong>corticothérapie générale à fortes doses doit être initiée IMMÉDIATEMENT</strong>, sans attendre la biopsie de l'artère temporale, afin de prévenir la bilatéralisation et d'autres complications ischémiques.</p>"},{"i":"c403d8c61889","n":82,"o":"82-7","u":"Identifier une urgence","t":"Connaître la conduite à tenir devant une baisse de vision brutale avec œil blanc et identification des urgences","q":"Quelle est la particularité clinique d'une baisse d'acuité visuelle (BAV) brutale avec œil blanc qui oriente le diagnostic en urgence ?","a":"<p>La présence d'un <strong>œdème papillaire</strong> est un signe crucial nécessitant une évacuation urgente. L'œil est <strong>indolore</strong>.</p>"},{"i":"e53529a4b570","n":82,"o":"82-7","u":"Identifier une urgence","t":"Connaître la conduite à tenir devant une baisse de vision brutale avec œil blanc et identification des urgences","q":"Quels diagnostics sont à évoquer devant une BAV brutale unilatérale, indolore, avec œil blanc et un FO ANORMAL ?","a":"<ul><li><strong>Occlusion de l'artère centrale de la rétine (OACR)</strong> : <strong>tache rouge cerise</strong>, mydriase aréflective.</li><li><strong>Occlusion de la veine centrale de la rétine (OVCR)</strong> : veines tortueuses et dilatées, hémorragies en flammèches ou en tâches, œdème papillaire ou maculaire, nodules cotonneux.</li><li><strong>Neuropathie optique ischémique antérieure aiguë (NOIAA)</strong> : œdème papillaire pâle, hémorragies en flammèches, déficit altitudinal.</li><li><strong>Dégénérescence maculaire liée à l'âge (DMLA) exsudative</strong> : hémorragies maculaires, exsudats secs, œdème ou décollement maculaire.</li><li><strong>Décollement de rétine (DR) rhegmatogène</strong> : rétine en relief, mobile, plis, déhiscence.</li></ul>"}]};